AIMED.سجّل({"slug":"drug-compendium","عنوان":"Drug Compendium by System","تمهيد":"","أقسام":[{"معرّف":"2-respiratory-system","عنوان":"2. RESPIRATORY SYSTEM","html":"<h3 id=\"21-bronchodilators\">2.1 Bronchodilators</h3><h3 id=\"short-acting-beta-2-agonists-saba\">Short-Acting Beta-2 Agonists / SABA</h3><ul><li>Albuterol / Salbutamol</li><li>Levalbuterol</li><li>Terbutaline</li><li>Pirbuterol</li></ul><h3 id=\"long-acting-beta-2-agonists-laba\">Long-Acting Beta-2 Agonists / LABA</h3><ul><li>Salmeterol</li><li>Formoterol (also rapid onset)</li><li>Vilanterol</li><li>Olodaterol</li><li>Indacaterol</li></ul><h3 id=\"short-acting-muscarinic-antagonists-sama\">Short-Acting Muscarinic Antagonists / SAMA</h3><ul><li>Ipratropium Bromide</li><li>Oxitropium</li></ul><h3 id=\"long-acting-muscarinic-antagonists-lama\">Long-Acting Muscarinic Antagonists / LAMA</h3><ul><li>Tiotropium Bromide</li><li>Umeclidinium</li><li>Glycopyrronium / Glycopyrrolate</li><li>Aclidinium</li><li>Revefenacin</li></ul><h3 id=\"22-inhaled-corticosteroids-ics\">2.2 Inhaled Corticosteroids / ICS</h3><ul><li>Fluticasone Propionate</li><li>Fluticasone Furoate</li><li>Budesonide</li><li>Beclomethasone Dipropionate</li><li>Mometasone Furoate</li><li>Ciclesonide</li></ul><h3 id=\"23-combination-inhalers\">2.3 Combination Inhalers</h3><h3 id=\"ics-laba\">ICS + LABA</h3><ul><li>Fluticasone Propionate/Salmeterol</li><li>Fluticasone Furoate/Vilanterol</li><li>Budesonide/Formoterol</li><li>Beclomethasone/Formoterol</li><li>Mometasone/Formoterol</li></ul><h3 id=\"laba-lama\">LABA + LAMA</h3><ul><li>Vilanterol/Umeclidinium</li><li>Formoterol/Glycopyrronium</li><li>Olodaterol/Tiotropium</li><li>Indacaterol/Glycopyrronium</li></ul><ul><li><strong>ICS + LABA + LAMA</strong> (Triple Therapy)<ul><li>Fluticasone Furoate/Vilanterol/Umeclidinium</li><li>Budesonide/Formoterol/Glycopyrronium</li><li>Beclomethasone/Formoterol/Glycopyrronium</li></ul></li></ul><h3 id=\"24-leukotriene-modifiers\">2.4 Leukotriene Modifiers</h3><ul><li>Montelukast (LTRA — Leukotriene Receptor Antagonist)</li><li>Zafirlukast (LTRA)</li><li>Zileuton (5-Lipoxygenase Inhibitor)</li></ul><h3 id=\"25-mast-cell-stabilizers\">2.5 Mast Cell Stabilizers</h3><ul><li>Cromolyn Sodium / Sodium Cromoglycate</li><li>Nedocromil</li></ul><h3 id=\"26-methylxanthines\">2.6 Methylxanthines</h3><ul><li>Theophylline</li><li>Aminophylline (theophylline-ethylenediamine)</li><li>Doxofylline</li></ul><h3 id=\"27-phosphodiesterase-4-inhibitors\">2.7 Phosphodiesterase-4 Inhibitors</h3><ul><li>Roflumilast (for severe COPD)</li><li>Apremilast (for psoriasis/PsA)</li></ul><h3 id=\"28-monoclonal-antibodies-for-severe-asthma\">2.8 Monoclonal Antibodies for Severe Asthma</h3><ul><li>Omalizumab (anti-IgE)</li><li>Mepolizumab (anti-IL-5)</li><li>Reslizumab (anti-IL-5)</li><li>Benralizumab (anti-IL-5 receptor)</li><li>Dupilumab (anti-IL-4 receptor α)</li><li>Tezepelumab (anti-TSLP / Thymic Stromal Lymphopoietin)</li></ul><h3 id=\"29-other-respiratory-agents\">2.9 Other Respiratory Agents</h3><ul><li>Dornase Alfa (rhDNase / Pulmozyme, for Cystic Fibrosis)</li><li>Ivacaftor, Lumacaftor, Tezacaftor, Elexacaftor (CFTR modulators)</li><li>A1-Antitrypsin (replacement therapy)</li></ul><h3 id=\"210-cough-cold-preparations\">2.10 Cough &amp; Cold Preparations</h3><ul><li><strong>Antitussives</strong> (Central)<ul><li>Dextromethorphan</li><li>Codeine</li><li>Butamirate</li><li>Benzonatate (peripheral, local anesthetic on stretch receptors)</li></ul></li></ul><h3 id=\"expectorants\">Expectorants</h3><ul><li>Guaifenesin</li></ul><h3 id=\"mucolytics\">Mucolytics</h3><ul><li>Acetylcysteine / N-Acetylcysteine (NAC)</li><li>Carbocisteine</li><li>Erdosteine</li><li>Bromhexine</li><li>Ambroxol</li></ul><h3 id=\"decongestants\">Decongestants</h3><ul><li>Oxymetazoline (topical)</li><li>Xylometazoline</li><li>Pseudoephedrine (oral, α1 agonist)</li><li>Phenylephrine (oral, α1 agonist)</li></ul>"},{"معرّف":"4-endocrine-system-metabolism","عنوان":"4. ENDOCRINE SYSTEM & METABOLISM","html":"<h3 id=\"41-diabetes-mellitus\">4.1 Diabetes Mellitus</h3><h3 id=\"411-insulins\">4.1.1 Insulins</h3><h3 id=\"ultra-rapid-acting\">Ultra-Rapid Acting</h3><ul><li>Lispro</li><li>Aspart</li><li>Glulisine</li><li>Faster Aspart (Fiasp)</li></ul><h3 id=\"short-acting\">Short-Acting</h3><ul><li>Regular Human Insulin / Soluble Insulin</li></ul><h3 id=\"intermediate-acting\">Intermediate-Acting</h3><ul><li>NPH / Isophane Insulin</li></ul><h3 id=\"long-acting-basal\">Long-Acting / Basal</h3><ul><li>Glargine U-100</li><li>Glargine U-300</li><li>Detemir</li><li>Degludec</li></ul><h3 id=\"ultra-long-acting\">Ultra-Long-Acting</h3><ul><li>Insulin Icodec (weekly)</li></ul><h3 id=\"pre-mixed-biphasic\">Pre-Mixed / Biphasic</h3><ul><li>70/30 (NPH/Regular)</li><li>75/25 (Lispro Protamine/Lispro)</li><li>70/30 (Aspart Protamine/Aspart)</li></ul><h3 id=\"412-oral-injectable-non-insulin-agents\">4.1.2 Oral &amp; Injectable Non-Insulin Agents</h3><h3 id=\"biguanides\">Biguanides</h3><ul><li>Metformin</li></ul><h3 id=\"sulfonylureas\">Sulfonylureas</h3><ul><li>Glibenclamide / Glyburide</li><li>Glipizide</li><li>Gliclazide</li><li>Glimepiride</li><li>Chlorpropamide</li></ul><h3 id=\"meglitinides-glinides\">Meglitinides / Glinides</h3><ul><li>Repaglinide</li><li>Nateglinide</li></ul><h3 id=\"thiazolidinediones-tzds-glitazones\">Thiazolidinediones / TZDs / Glitazones</h3><ul><li>Pioglitazone</li><li>Rosiglitazone (restricted)</li></ul><h3 id=\"alpha-glucosidase-inhibitors\">Alpha-Glucosidase Inhibitors</h3><ul><li>Acarbose</li><li>Miglitol</li><li>Voglibose</li></ul><ul><li><strong>DPP-4 Inhibitors / Gliptins</strong> (suffix: &quot;-gliptin&quot;)<ul><li>Sitagliptin</li><li>Linagliptin</li><li>Saxagliptin</li><li>Alogliptin</li><li>Vildagliptin</li></ul></li><li><strong>GLP-1 Receptor Agonists</strong> (suffix: &quot;-glutide&quot; or &quot;-natide&quot;)<ul><li>Short-acting: Exenatide, Lixisenatide</li><li>Long-acting: Liraglutide, Dulaglutide, Semaglutide (oral + injectable)</li></ul></li><li><strong>SGLT2 Inhibitors / Gliflozins</strong> (suffix: &quot;-gliflozin&quot;)<ul><li>Empagliflozin</li><li>Dapagliflozin</li><li>Canagliflozin</li><li>Ertugliflozin</li></ul></li></ul><h3 id=\"dopamine-agonist\">Dopamine Agonist</h3><ul><li>Bromocriptine (quick-release)</li></ul><h3 id=\"bile-acid-sequestrant\">Bile Acid Sequestrant</h3><ul><li>Colesevelam</li></ul><h3 id=\"amylin-analog\">Amylin Analog</h3><ul><li>Pramlintide</li></ul><h3 id=\"dual-gipglp-1-agonist\">Dual GIP/GLP-1 Agonist</h3><ul><li>Tirzepatide</li></ul><h3 id=\"413-glucose-management-in-hospital\">4.1.3 Glucose Management in Hospital</h3><ul><li>Glucagon (Subcutaneous / IM / Intranasal)</li><li>Dextrose 50% (D50W)</li><li>Dextrose 25%</li><li>Dextrose 10%</li><li>Dextrose 5%</li></ul><h3 id=\"42-thyroid\">4.2 Thyroid</h3><h3 id=\"421-thyroid-hormone-replacement\">4.2.1 Thyroid Hormone Replacement</h3><ul><li>Levothyroxine (T4)</li><li>Liothyronine (T3, rarely used)</li><li>Desiccated Thyroid Extract (Armour Thyroid)</li></ul><h3 id=\"422-antithyroid-drugs-thionamides\">4.2.2 Antithyroid Drugs / Thionamides</h3><ul><li>Methimazole (Thiamazole)</li><li>Propylthiouracil / PTU (preferred in 1st trimester)</li><li>Carbimazole (prodrug → methimazole)</li></ul><h3 id=\"423-iodine-preparations\">4.2.3 Iodine Preparations</h3><ul><li>Lugol&#39;s Solution / Potassium Iodide</li><li>Saturated Solution of Potassium Iodide / SSKI</li></ul><h3 id=\"43-corticosteroids\">4.3 Corticosteroids</h3><h3 id=\"431-glucocorticoids\">4.3.1 Glucocorticoids</h3><ul><li><strong>Short-Acting</strong> (8-12h)<ul><li>Hydrocortisone</li></ul></li><li><strong>Intermediate-Acting</strong> (12-36h)<ul><li>Prednisone (prodrug → prednisolone)</li><li>Prednisolone</li><li>Methylprednisolone</li><li>Triamcinolone</li></ul></li><li><strong>Long-Acting</strong> (36-72h)<ul><li>Dexamethasone</li><li>Betamethasone</li></ul></li></ul><h3 id=\"432-mineralocorticoids\">4.3.2 Mineralocorticoids</h3><ul><li>Fludrocortisone</li></ul><h3 id=\"433-steroidogenesis-inhibitors\">4.3.3 Steroidogenesis Inhibitors</h3><ul><li>Ketoconazole (also antifungal)</li><li>Metyrapone</li><li>Mitotane</li><li>Osilodrostat</li><li>Etomidate (at sedative doses, inhibits 11β-hydroxylase)</li></ul><h3 id=\"434-adrenal-enzyme-inhibitors\">4.3.4 Adrenal Enzyme Inhibitors</h3><ul><li>Aminoglutethimide (obsolete, inhibits desmolase)</li></ul><h3 id=\"44-calcium-bone\">4.4 Calcium &amp; Bone</h3><h3 id=\"441-bisphosphonates-antiresorptive\">4.4.1 Bisphosphonates (antiresorptive)</h3><ul><li>Alendronate</li><li>Risedronate</li><li>Zoledronic Acid / Zoledronate</li><li>Pamidronate</li><li>Ibandronate</li><li>Etidronate</li></ul><h3 id=\"442-rankl-inhibitor\">4.4.2 RANKL Inhibitor</h3><ul><li>Denosumab (monoclonal antibody)</li></ul><h3 id=\"443-parathyroid-hormone-analogues-anabolic\">4.4.3 Parathyroid Hormone Analogues (anabolic)</h3><ul><li>Teriparatide (PTH 1-34)</li><li>Abaloparatide (PTHrP analogue)</li></ul><h3 id=\"444-sclerostin-inhibitor\">4.4.4 Sclerostin Inhibitor</h3><ul><li>Romosozumab</li></ul><h3 id=\"445-serms-selective-estrogen-receptor-modulators\">4.4.5 SERMs (Selective Estrogen Receptor Modulators)</h3><ul><li>Raloxifene</li></ul><h3 id=\"446-calcitonin\">4.4.6 Calcitonin</h3><ul><li>Salmon Calcitonin</li></ul><h3 id=\"447-vitamin-d-analogues\">4.4.7 Vitamin D &amp; Analogues</h3><ul><li>Cholecalciferol (Vitamin D3)</li><li>Ergocalciferol (Vitamin D2)</li><li>Calcitriol (1,25-dihydroxyvitamin D3)</li><li>Alfacalcidol (1α-hydroxyvitamin D3)</li><li>Paricalcitol (synthetic, less calcemic)</li><li>Doxercalciferol</li></ul><h3 id=\"448-calcium-preparations\">4.4.8 Calcium Preparations</h3><ul><li>Calcium Carbonate</li><li>Calcium Citrate</li><li>Calcium Gluconate (IV)</li></ul><h3 id=\"449-calcimimetics\">4.4.9 Calcimimetics</h3><ul><li>Cinacalcet</li></ul><h3 id=\"45-pituitary-growth\">4.5 Pituitary &amp; Growth</h3><ul><li>Somatropin (Recombinant Human Growth Hormone)</li><li>Octreotide (Somatostatin Analog)</li><li>Lanreotide</li><li>Pasireotide</li><li>Pegvisomant (GH Receptor Antagonist)</li></ul><h3 id=\"dopamine-agonists\">Dopamine Agonists</h3><ul><li>Bromocriptine</li><li>Cabergoline</li></ul><h3 id=\"gnrh-agonists\">GnRH Agonists</h3><ul><li>Leuprolide</li><li>Goserelin</li><li>Triptorelin</li></ul><h3 id=\"gnrh-antagonists\">GnRH Antagonists</h3><ul><li>Cetrorelix</li><li>Ganirelix</li><li>Degarelix</li></ul><ul><li><strong>Desmopressin / DDAVP</strong> (Vasopressin V2 Agonist)</li></ul><h3 id=\"vasopressin-antagonists-vaptans\">Vasopressin Antagonists / Vaptans</h3><ul><li>Tolvaptan</li></ul><h3 id=\"46-reproductive-endocrinology\">4.6 Reproductive Endocrinology</h3><h3 id=\"estrogens\">Estrogens</h3><ul><li>Ethinyl Estradiol</li><li>Estradiol</li><li>Conjugated Equine Estrogens</li></ul><h3 id=\"progestins\">Progestins</h3><ul><li>Medroxyprogesterone Acetate</li><li>Norethindrone</li><li>Levonorgestrel</li><li>Desogestrel</li><li>Drospirenone</li><li>Micronized Progesterone</li></ul><h3 id=\"oral-contraceptives\">Oral Contraceptives</h3><ul><li>Combined Oral Contraceptives (COCs)</li><li>Progestin-Only Pills (POPs)</li></ul><h3 id=\"emergency-contraception\">Emergency Contraception</h3><ul><li>Levonorgestrel (Plan B)</li><li>Ulipristal Acetate (Ella)</li></ul><h3 id=\"anti-androgens\">Anti-Androgens</h3><ul><li>Cyproterone Acetate</li><li>Spironolactone</li></ul>"},{"معرّف":"5-central-nervous-system","عنوان":"5. CENTRAL NERVOUS SYSTEM","html":"<h3 id=\"51-sedative-hypnotics-anxiolytics\">5.1 Sedative-Hypnotics &amp; Anxiolytics</h3><h3 id=\"benzodiazepines\">Benzodiazepines</h3><ul><li>Short-acting: Midazolam, Triazolam</li><li>Intermediate: Lorazepam, Alprazolam, Temazepam</li><li>Long-acting: Diazepam, Clonazepam, Chlordiazepoxide, Clorazepate</li></ul><h3 id=\"z-drugs-non-benzodiazepine-hypnotics\">Z-Drugs / Non-Benzodiazepine Hypnotics</h3><ul><li>Zolpidem</li><li>Zopiclone</li><li>Eszopiclone</li><li>Zaleplon</li></ul><h3 id=\"barbiturates\">Barbiturates</h3><ul><li>Phenobarbital</li><li>Butalbital (in combination for headache)</li><li>Thiopental (induction anesthetic)</li><li>Primidone (→ phenobarbital)</li></ul><h3 id=\"melatonin-receptor-agonists\">Melatonin Receptor Agonists</h3><ul><li>Ramelteon</li></ul><h3 id=\"orexin-receptor-antagonists\">Orexin Receptor Antagonists</h3><ul><li>Suvorexant</li><li>Lemborexant</li><li>Daridorexant</li></ul><ul><li><strong>Buspirone</strong> (5-HT1A partial agonist)</li></ul><h3 id=\"52-antidepressants\">5.2 Antidepressants</h3><h3 id=\"selective-serotonin-reuptake-inhibitors-ssris\">Selective Serotonin Reuptake Inhibitors / SSRIs</h3><ul><li>Fluoxetine</li><li>Sertraline</li><li>Paroxetine</li><li>Citalopram</li><li>Escitalopram (S-enantiomer of citalopram)</li><li>Fluvoxamine</li></ul><h3 id=\"serotonin-norepinephrine-reuptake-inhibitors-snris\">Serotonin-Norepinephrine Reuptake Inhibitors / SNRIs</h3><ul><li>Venlafaxine</li><li>Desvenlafaxine</li><li>Duloxetine</li><li>Levomilnacipran</li><li>Milnacipran</li></ul><h3 id=\"tricyclic-antidepressants-tcas\">Tricyclic Antidepressants / TCAs</h3><ul><li>Amitriptyline</li><li>Nortriptyline</li><li>Imipramine</li><li>Desipramine</li><li>Clomipramine</li><li>Doxepin</li><li>Trimipramine</li><li>Protriptyline</li></ul><h3 id=\"tetracyclic-atypical-antidepressants\">Tetracyclic / Atypical Antidepressants</h3><ul><li>Mirtazapine (NaSSA)</li><li>Trazodone (SARI)</li><li>Nefazodone</li><li>Bupropion (NDRI)</li><li>Vilazodone (SPARI / 5-HT1A partial agonist)</li><li>Vortioxetine (multimodal)</li><li>Agomelatine (MT1/MT2 agonist, 5-HT2C antagonist)</li></ul><h3 id=\"monoamine-oxidase-inhibitors-maois\">Monoamine Oxidase Inhibitors / MAOIs</h3><ul><li>Phenelzine</li><li>Tranylcypromine</li><li>Isocarboxazid</li><li>Selegiline (transdermal, selective MAO-B at low dose)</li></ul><ul><li><strong>NMDA Antagonist</strong> (for TRD)<ul><li>Esketamine (intranasal)</li></ul></li></ul><h3 id=\"53-mood-stabilizers\">5.3 Mood Stabilizers</h3><ul><li>Lithium Carbonate</li><li>Valproic Acid / Valproate / Divalproex Sodium</li><li>Carbamazepine</li><li>Oxcarbazepine</li><li>Lamotrigine</li><li>Topiramate (also antiepileptic)</li><li>Gabapentin (off-label, also antiepileptic)</li></ul><h3 id=\"54-antipsychotics\">5.4 Antipsychotics</h3><h3 id=\"first-generation-typical\">First-Generation / Typical</h3><ul><li>High Potency: Haloperidol, Fluphenazine, Trifluoperazine</li><li>Low Potency: Chlorpromazine, Thioridazine</li><li>Other: Loxapine, Molindone, Perphenazine</li></ul><h3 id=\"second-generation-atypical\">Second-Generation / Atypical</h3><ul><li>Risperidone</li><li>Paliperidone</li><li>Olanzapine</li><li>Quetiapine</li><li>Clozapine (risk of agranulocytosis)</li><li>Aripiprazole</li><li>Brexpiprazole</li><li>Cariprazine</li><li>Lurasidone</li><li>Ziprasidone</li><li>Asenapine</li><li>Iloperidone</li><li>Lumateperone</li></ul><h3 id=\"long-acting-injectable-lai-antipsychotics\">Long-Acting Injectable / LAI Antipsychotics</h3><ul><li>Fluphenazine Decanoate</li><li>Haloperidol Decanoate</li><li>Risperidone Microspheres</li><li>Paliperidone Palmitate</li><li>Aripiprazole LAI</li><li>Olanzapine Pamoate</li></ul><h3 id=\"55-antiepileptics-anticonvulsants\">5.5 Antiepileptics / Anticonvulsants</h3><h3 id=\"first-generation\">First Generation</h3><ul><li>Phenytoin</li><li>Fosphenytoin (prodrug, IV)</li><li>Phenobarbital</li><li>Primidone</li><li>Carbamazepine</li><li>Valproic Acid</li><li>Ethosuximide (for absence)</li></ul><h3 id=\"second-generation\">Second Generation</h3><ul><li>Lamotrigine</li><li>Topiramate</li><li>Levetiracetam</li><li>Brivaracetam</li><li>Gabapentin</li><li>Pregabalin</li><li>Oxcarbazepine</li><li>Eslicarbazepine</li><li>Zonisamide</li><li>Felbamate (restricted)</li><li>Tiagabine</li><li>Vigabatrin (restricted, visual field loss)</li><li>Rufinamide</li><li>Lacosamide</li><li>Perampanel (AMPA antagonist)</li></ul><h3 id=\"third-generation\">Third Generation</h3><ul><li>Cenobamate</li><li>Stiripentol (for Dravet)</li><li>Cannabidiol / Epidiolex (for Lennox-Gastaut, Dravet)</li><li>Fenfluramine (for Dravet)</li></ul><ul><li><strong>Benzodiazepines</strong> (for acute seizure)<ul><li>Lorazepam (first-line IV)</li><li>Midazolam (IM, buccal, intranasal)</li><li>Diazepam (rectal, IV)</li><li>Clonazepam</li></ul></li></ul><h3 id=\"56-parkinsons-disease-movement-disorders\">5.6 Parkinson&#39;s Disease &amp; Movement Disorders</h3><h3 id=\"dopamine-precursor\">Dopamine Precursor</h3><ul><li>Levodopa / L-DOPA + Carbidopa (Sinemet)</li><li>Levodopa + Benserazide (Madopar)</li></ul><ul><li><strong>COMT Inhibitors</strong> (peripheral)<ul><li>Entacapone</li><li>Tolcapone (hepatotoxic)</li><li>Opicapone</li></ul></li></ul><h3 id=\"dopamine-agonists\">Dopamine Agonists</h3><ul><li>Pramipexole</li><li>Ropinirole</li><li>Rotigotine (transdermal patch)</li><li>Apomorphine (rescue, injection/infusion)</li></ul><h3 id=\"mao-b-inhibitors\">MAO-B Inhibitors</h3><ul><li>Selegiline</li><li>Rasagiline</li><li>Safinamide</li></ul><ul><li><strong>Anticholinergics</strong> (Centrally acting)<ul><li>Benztropine / Benzatropine</li><li>Trihexyphenidyl</li><li>Biperiden</li></ul></li></ul><h3 id=\"others\">Others</h3><ul><li>Amantadine (NMDA antagonist, antiviral)</li><li>Istradefylline (Adenosine A2A antagonist)</li></ul><h3 id=\"57-alzheimers-dementia\">5.7 Alzheimer&#39;s Dementia</h3><ul><li><strong>Cholinesterase Inhibitors</strong> (suffix: &quot;-stigmine&quot; / &quot;-pezil&quot;)<ul><li>Donepezil</li><li>Rivastigmine</li><li>Galantamine</li></ul></li></ul><h3 id=\"nmda-receptor-antagonist\">NMDA Receptor Antagonist</h3><ul><li>Memantine</li><li>Memantine + Donepezil (combination)</li></ul><ul><li><strong>Monoclonal Antibodies</strong> (anti-amyloid)<ul><li>Aducanumab (discontinued in many regions)</li><li>Lecanemab</li><li>Donanemab</li></ul></li></ul><h3 id=\"58-multiple-sclerosis\">5.8 Multiple Sclerosis</h3><h3 id=\"injectable-disease-modifying-therapies\">Injectable Disease-Modifying Therapies</h3><ul><li>Interferon Beta-1a, Beta-1b</li><li>Glatiramer Acetate</li></ul><h3 id=\"oral\">Oral</h3><ul><li>Fingolimod (S1P modulator)</li><li>Siponimod (S1P modulator)</li><li>Ozanimod (S1P modulator)</li><li>Dimethyl Fumarate</li><li>Diroximel Fumarate</li><li>Teriflunomide</li><li>Cladribine</li></ul><h3 id=\"monoclonal-antibodies-infusions\">Monoclonal Antibodies / Infusions</h3><ul><li>Natalizumab</li><li>Ocrelizumab (anti-CD20)</li><li>Ofatumumab (anti-CD20)</li><li>Ublituximab (anti-CD20)</li><li>Alemtuzumab (anti-CD52)</li></ul><h3 id=\"59-pain-analgesia\">5.9 Pain &amp; Analgesia</h3><h3 id=\"non-steroidal-anti-inflammatory-drugs-nsaids\">Non-Steroidal Anti-Inflammatory Drugs / NSAIDs</h3><ul><li>Non-Selective: Ibuprofen, Naproxen, Diclofenac, Indomethacin, Ketorolac</li><li>COX-2 Selective / Coxibs: Celecoxib, Etoricoxib, Parecoxib (IV)</li></ul><h3 id=\"acetaminophen-paracetamol\">Acetaminophen / Paracetamol</h3><h3 id=\"opioids\">Opioids</h3><ul><li>Natural Alkaloids: Morphine, Codeine</li><li>Semi-Synthetic: Oxycodone, Hydromorphone, Hydrocodone, Oxymorphone, Buprenorphine</li><li>Synthetic: Fentanyl, Methadone, Tramadol, Meperidine / Pethidine, Tapentadol</li><li>Partial Agonists: Buprenorphine, Butorphanol</li><li>Mixed Agonist-Antagonist: Nalbuphine, Pentazocine</li></ul><h3 id=\"adjuvant-analgesics\">Adjuvant Analgesics</h3><ul><li>Gabapentinoids: Gabapentin, Pregabalin</li><li>SNRIs: Duloxetine, Venlafaxine</li><li>TCAs: Amitriptyline, Nortriptyline</li><li>Topicals: Lidocaine Patch, Capsaicin</li></ul><h3 id=\"510-anesthetics\">5.10 Anesthetics</h3><h3 id=\"local-anesthetics\">Local Anesthetics</h3><ul><li>Esters: Cocaine, Procaine, Tetracaine, Benzocaine</li><li>Amides: Lidocaine, Bupivacaine, Ropivacaine, Mepivacaine, Prilocaine</li></ul><h3 id=\"general-anesthetics\">General Anesthetics</h3><ul><li>Inhaled / Volatile: Sevoflurane, Isoflurane, Desflurane, Halothane, Nitrous Oxide</li><li>IV Induction Agents: Propofol, Etomidate, Ketamine, Midazolam, Thiopental</li></ul><h3 id=\"neuromuscular-blocking-agents\">Neuromuscular Blocking Agents</h3><ul><li>Depolarizing: Succinylcholine / Suxamethonium</li><li>Non-Depolarizing:<ul><li>Aminosteroidal: Rocuronium, Vecuronium, Pancuronium</li><li>Benzylisoquinolinium: Cisatracurium, Atracurium, Mivacurium</li></ul></li></ul><h3 id=\"reversal-of-neuromuscular-block\">Reversal of Neuromuscular Block</h3><ul><li>Neostigmine + Glycopyrrolate (or Atropine)</li><li>Sugammadex (for Rocuronium/Vecuronium)</li></ul>"},{"معرّف":"6-anti-infective-agents","عنوان":"6. ANTI-INFECTIVE AGENTS","html":"<h3 id=\"61-antibacterial-agents\">6.1 Antibacterial Agents</h3><h3 id=\"611-beta-lactams\">6.1.1 Beta-Lactams</h3><h3 id=\"penicillins\">Penicillins</h3><ul><li>Natural: Penicillin G (IV/IM), Penicillin V (PO), Benzathine Penicillin G (LAI)</li><li>Aminopenicillins: Amoxicillin, Ampicillin</li><li>Antistaphylococcal Penicillins: Dicloxacillin, Flucloxacillin, Nafcillin, Oxacillin, Methicillin</li><li>Antipseudomonal Penicillins: Piperacillin, Ticarcillin</li></ul><h3 id=\"beta-lactamase-inhibitor-combinations\">Beta-Lactamase Inhibitor Combinations</h3><ul><li>Amoxicillin-Clavulanate</li><li>Ampicillin-Sulbactam</li><li>Piperacillin-Tazobactam</li><li>Ceftolozane-Tazobactam</li><li>Ceftazidime-Avibactam</li><li>Meropenem-Vaborbactam</li><li>Imipenem-Cilastatin-Relebactam</li><li>Ticarcillin-Clavulanate</li></ul><h3 id=\"cephalosporins\">Cephalosporins</h3><ul><li>1st Generation: Cephalexin, Cefazolin, Cefadroxil</li><li>2nd Generation: Cefuroxime, Cefaclor, Cefprozil, Cefoxitin (cephamycin), Cefotetan</li><li>3rd Generation: Ceftriaxone, Cefotaxime, Ceftazidime, Cefixime, Cefpodoxime, Cefdinir, Cefditoren</li><li>4th Generation: Cefepime</li><li>5th Generation / Advanced: Ceftaroline, Ceftobiprole</li></ul><h3 id=\"carbapenems\">Carbapenems</h3><ul><li>Meropenem</li><li>Imipenem-Cilastatin</li><li>Ertapenem</li><li>Doripenem</li></ul><h3 id=\"monobactams\">Monobactams</h3><ul><li>Aztreonam</li></ul><h3 id=\"612-glycopeptides-lipopeptides\">6.1.2 Glycopeptides &amp; Lipopeptides</h3><ul><li>Vancomycin</li><li>Teicoplanin</li><li>Dalbavancin</li><li>Oritavancin</li><li>Telavancin</li><li>Daptomycin (lipopeptide)</li></ul><h3 id=\"613-oxazolidinones\">6.1.3 Oxazolidinones</h3><ul><li>Linezolid</li><li>Tedizolid</li></ul><h3 id=\"614-macrolides-ketolides\">6.1.4 Macrolides &amp; Ketolides</h3><ul><li>Erythromycin</li><li>Azithromycin</li><li>Clarithromycin</li><li>Fidaxomicin (for C. difficile)</li><li>Telithromycin (ketolide, restricted)</li></ul><h3 id=\"615-aminoglycosides\">6.1.5 Aminoglycosides</h3><ul><li>Gentamicin</li><li>Amikacin</li><li>Tobramycin</li><li>Neomycin (topical/oral)</li><li>Streptomycin (TB)</li><li>Paromomycin</li></ul><h3 id=\"616-tetracyclines-glycylcyclines\">6.1.6 Tetracyclines &amp; Glycylcyclines</h3><ul><li>Doxycycline</li><li>Minocycline</li><li>Tetracycline</li><li>Demeclocycline (SIADH)</li><li>Tigecycline (glycylcycline)</li><li>Eravacycline</li><li>Omadacycline</li><li>Sarecycline</li></ul><h3 id=\"617-fluoroquinolones-suffix-floxacin\">6.1.7 Fluoroquinolones (suffix: &quot;-floxacin&quot;)</h3><ul><li>Ciprofloxacin</li><li>Levofloxacin</li><li>Moxifloxacin</li><li>Delafloxacin</li><li>Ofloxacin</li><li>Norfloxacin</li></ul><h3 id=\"618-other-antibiotics\">6.1.8 Other Antibiotics</h3><ul><li>Clindamycin (lincosamide)</li><li>Metronidazole (nitroimidazole)</li><li>Chloramphenicol</li><li>Trimethoprim-Sulfamethoxazole (TMP-SMX, Co-trimoxazole)</li><li>Nitrofurantoin</li><li>Fosfomycin</li><li>Colistin / Polymyxin E</li><li>Polymyxin B</li><li>Mupirocin (topical)</li><li>Bacitracin (topical)</li></ul><h3 id=\"619-antitubercular-agents\">6.1.9 Antitubercular Agents</h3><ul><li>First-Line: Isoniazid / INH, Rifampicin / Rifampin, Pyrazinamide, Ethambutol, Rifabutin</li><li>Second-Line: Amikacin, Kanamycin, Capreomycin, Levofloxacin, Moxifloxacin, Ethionamide, Cycloserine, Linezolid, Bedaquiline, Delamanid, Pretomanid, Clofazimine, Para-Aminosalicylic Acid / PAS</li></ul><h3 id=\"6110-antileprosy-agents\">6.1.10 Antileprosy Agents</h3><ul><li>Dapsone</li><li>Rifampicin</li><li>Clofazimine</li></ul><h3 id=\"62-antifungal-agents\">6.2 Antifungal Agents</h3><h3 id=\"azoles\">Azoles</h3><ul><li>Triazoles: Fluconazole, Voriconazole, Itraconazole, Posaconazole, Isavuconazole</li><li>Imidazoles: Ketoconazole, Clotrimazole, Miconazole, Econazole (mostly topical)</li></ul><ul><li><strong>Echinocandins</strong> (suffix: &quot;-fungin&quot;)<ul><li>Caspofungin</li><li>Micafungin</li><li>Anidulafungin</li></ul></li></ul><h3 id=\"polyenes\">Polyenes</h3><ul><li>Amphotericin B Deoxycholate</li><li>Liposomal Amphotericin B</li><li>Amphotericin B Lipid Complex</li><li>Nystatin (topical)</li></ul><h3 id=\"antimetabolite\">Antimetabolite</h3><ul><li>Flucytosine / 5-FC</li></ul><h3 id=\"allylamines\">Allylamines</h3><ul><li>Terbinafine (oral + topical)</li><li>Naftifine (topical)</li></ul><h3 id=\"griseofulvin\">Griseofulvin</h3><h3 id=\"63-antiviral-agents\">6.3 Antiviral Agents</h3><h3 id=\"631-anti-herpes\">6.3.1 Anti-Herpes</h3><ul><li>Acyclovir</li><li>Valacyclovir (prodrug)</li><li>Famciclovir (prodrug)</li><li>Penciclovir (topical)</li><li>Ganciclovir (for CMV)</li><li>Valganciclovir (oral for CMV)</li><li>Foscarnet (CMV retinitis, acyclovir-resistant HSV)</li><li>Cidofovir</li></ul><h3 id=\"632-anti-influenza\">6.3.2 Anti-Influenza</h3><ul><li>Neuraminidase Inhibitors: Oseltamivir, Zanamivir, Peramivir</li><li>Cap-dependent Endonuclease Inhibitor: Baloxavir Marboxil</li><li>M2 Inhibitors / Adamantanes (resistance): Amantadine, Rimantadine</li></ul><h3 id=\"633-hepatitis\">6.3.3 Hepatitis</h3><ul><li><strong>Hepatitis B</strong>: Tenofovir Disoproxil Fumarate, Tenofovir Alafenamide, Entecavir, Lamivudine, Adefovir, Telbivudine, Peginterferon Alfa-2a</li><li><strong>Hepatitis C</strong>: Direct Acting Antivirals / DAAs<ul><li>NS5A Inhibitors: Ledipasvir, Velpatasvir, Daclatasvir, Ombitasvir, Pibrentasvir</li><li>NS5B Inhibitors: Sofosbuvir, Dasabuvir</li><li>NS3/4A Protease Inhibitors: Glecaprevir, Grazoprevir, Voxilaprevir</li></ul></li></ul><h3 id=\"634-antiretrovirals-hiv\">6.3.4 Antiretrovirals (HIV)</h3><h3 id=\"nucleosidenucleotide-reverse-transcriptase-inhibitors-nrtis\">Nucleoside/Nucleotide Reverse Transcriptase Inhibitors / NRTIs</h3><ul><li>Tenofovir Disoproxil Fumarate (TDF)</li><li>Tenofovir Alafenamide (TAF)</li><li>Emtricitabine (FTC)</li><li>Lamivudine (3TC)</li><li>Abacavir</li><li>Zidovudine (AZT)</li><li>Stavudine (d4T, largely discontinued)</li><li>Didanosine (ddI, discontinued)</li><li>Zalcitabine (ddC, discontinued)</li></ul><h3 id=\"non-nucleoside-reverse-transcriptase-inhibitors-nnrtis\">Non-Nucleoside Reverse Transcriptase Inhibitors / NNRTIs</h3><ul><li>Efavirenz</li><li>Rilpivirine</li><li>Etravirine</li><li>Doravirine</li><li>Nevirapine</li></ul><ul><li><strong>Protease Inhibitors / PIs</strong> (boosted with Ritonavir or Cobicistat)<ul><li>Darunavir</li><li>Atazanavir</li><li>Lopinavir</li><li>Tipranavir</li><li>Fosamprenavir</li></ul></li></ul><h3 id=\"integrase-strand-transfer-inhibitors-instis\">Integrase Strand Transfer Inhibitors / INSTIs</h3><ul><li>Dolutegravir</li><li>Bictegravir</li><li>Raltegravir</li><li>Cabotegravir (oral + LAI)</li><li>Elvitegravir</li></ul><h3 id=\"entry-inhibitors\">Entry Inhibitors</h3><ul><li>Maraviroc (CCR5 Antagonist)</li><li>Enfuvirtide (fusion inhibitor, T-20)</li></ul><h3 id=\"attachment-inhibitor\">Attachment Inhibitor</h3><ul><li>Fostemsavir</li></ul><h3 id=\"post-attachment-inhibitor\">Post-Attachment Inhibitor</h3><ul><li>Ibalizumab (anti-CD4)</li></ul><h3 id=\"pharmacokinetic-enhancers\">Pharmacokinetic Enhancers</h3><ul><li>Ritonavir (low dose)</li><li>Cobicistat</li></ul><h3 id=\"635-covid-19\">6.3.5 COVID-19</h3><ul><li>Remdesivir</li><li>Nirmatrelvir/Ritonavir (Paxlovid)</li><li>Molnupiravir</li><li>Baricitinib (JAK inhibitor)</li><li>Tocilizumab (anti-IL-6)</li></ul>"},{"معرّف":"7-hematology","عنوان":"7. HEMATOLOGY","html":"<h3 id=\"hematopoietic-growth-factors\">Hematopoietic Growth Factors</h3><ul><li>Erythropoietin / Epoetin Alfa</li><li>Darbepoetin Alfa</li><li>Filgrastim (G-CSF)</li><li>Pegfilgrastim</li><li>Sargramostim (GM-CSF)</li></ul><h3 id=\"iron-preparations\">Iron Preparations</h3><ul><li>Ferrous Sulfate</li><li>Ferrous Gluconate</li><li>Ferrous Fumarate</li><li>Iron Sucrose (IV)</li><li>Ferric Carboxymaltose (IV)</li><li>Iron Dextran (IV)</li><li>Ferumoxytol (IV)</li></ul><h3 id=\"vitamin-b12-folate\">Vitamin B12 &amp; Folate</h3><ul><li>Cyanocobalamin</li><li>Hydroxocobalamin</li><li>Folic Acid</li><li>Leucovorin / Folinic Acid (rescue)</li></ul><h3 id=\"chelating-agents\">Chelating Agents</h3><ul><li>Deferoxamine / Desferrioxamine</li><li>Deferasirox</li><li>Deferiprone</li></ul><h3 id=\"hemostasis-agents\">Hemostasis Agents</h3><ul><li>Desmopressin / DDAVP (releases vWF)</li><li>Factor VIII (Hemophilia A)</li><li>Factor IX (Hemophilia B)</li><li>Emicizumab (bispecific antibody, Hemophilia A)</li></ul>"},{"معرّف":"8-immunology-transplantation","عنوان":"8. IMMUNOLOGY & TRANSPLANTATION","html":"<h3 id=\"calcineurin-inhibitors\">Calcineurin Inhibitors</h3><ul><li>Cyclosporine</li><li>Tacrolimus</li></ul><h3 id=\"antimetabolites\">Antimetabolites</h3><ul><li>Mycophenolate Mofetil (MMF)</li><li>Azathioprine</li></ul><h3 id=\"mtor-inhibitors\">mTOR Inhibitors</h3><ul><li>Sirolimus (Rapamycin)</li><li>Everolimus</li></ul><h3 id=\"biologics\">Biologics</h3><ul><li>Basiliximab (anti-CD25, IL-2 receptor antagonist)</li><li>Antithymocyte Globulin (ATG, Rabbit or Equine)</li><li>Belatacept (CTLA-4-Ig)</li></ul>"},{"معرّف":"9-dermatology","عنوان":"9. DERMATOLOGY","html":"<ul><li><strong>Topical Corticosteroids</strong> (by potency)<ul><li>Low: Hydrocortisone 1%</li><li>Medium: Triamcinolone Acetonide</li><li>High: Betamethasone Dipropionate</li><li>Very High: Clobetasol Propionate</li></ul></li><li><strong>Calcineurin Inhibitors</strong> (topical)<ul><li>Tacrolimus Ointment</li><li>Pimecrolimus Cream</li></ul></li></ul><h3 id=\"retinoids\">Retinoids</h3><ul><li>Topical: Tretinoin, Adapalene, Tazarotene, Trifarotene</li><li>Oral: Isotretinoin, Acitretin</li></ul><h3 id=\"agents-for-psoriasis\">Agents for Psoriasis</h3><ul><li>Biologics: Adalimumab, Ustekinumab, Secukinumab (anti-IL-17A), Ixekizumab, Brodalumab, Guselkumab (anti-IL-23), Risankizumab, Tildrakizumab</li><li>Apremilast (PDE-4 inhibitor)</li><li>Deucravacitinib (TYK2 inhibitor)</li></ul>"},{"معرّف":"10-iv-fluids-solutions","عنوان":"10. IV FLUIDS & SOLUTIONS","html":"<h3 id=\"101-crystalloids\">10.1 Crystalloids</h3><h3 id=\"replacement-isotonic\">Replacement / Isotonic</h3><ul><li>0.9% Sodium Chloride / Normal Saline</li><li>Ringer&#39;s Lactate / Hartmann&#39;s Solution</li><li>Plasma-Lyte / Plasmalyte</li></ul><h3 id=\"maintenance\">Maintenance</h3><ul><li>0.45% Sodium Chloride (Half-Normal Saline)</li><li>5% Dextrose in Water (D5W)</li><li>5% Dextrose in 0.45% NaCl</li><li>5% Dextrose in 0.9% NaCl</li></ul><h3 id=\"volume-expansion\">Volume Expansion</h3><ul><li>3% Sodium Chloride (Hypertonic Saline)</li><li>7.5% Sodium Chloride</li></ul><h3 id=\"special-solutions\">Special Solutions</h3><ul><li>8.4% Sodium Bicarbonate</li><li>Mannitol 20%</li><li>50% Dextrose (D50W)</li></ul><h3 id=\"102-colloids\">10.2 Colloids</h3><ul><li>Albumin 5% (Isotonic)</li><li>Albumin 25% (Hyperoncotic)</li><li>Hydroxyethyl Starch / HES (restricted use)</li></ul><h3 id=\"103-blood-products\">10.3 Blood Products</h3><ul><li>Packed Red Blood Cells (PRBCs)</li><li>Fresh Frozen Plasma (FFP)</li><li>Platelets</li><li>Cryoprecipitate</li><li>Prothrombin Complex Concentrate / PCC (3-Factor, 4-Factor)</li></ul><h3 id=\"104-parenteral-nutrition\">10.4 Parenteral Nutrition</h3><ul><li>Total Parenteral Nutrition (TPN)</li><li>Peripheral Parenteral Nutrition (PPN)</li><li>Intravenous Lipid Emulsion (e.g., Intralipid)</li></ul>"},{"معرّف":"11-emergency-critical-care-drugs","عنوان":"11. EMERGENCY & CRITICAL CARE DRUGS","html":"<h3 id=\"111-cardiac-arrest-acls\">11.1 Cardiac Arrest / ACLS</h3><ul><li>Epinephrine / Adrenaline (1 mg q3-5 min)</li><li>Amiodarone (300 mg → 150 mg for VF/pVT)</li><li>Lidocaine (alternative to Amiodarone)</li><li>Magnesium Sulfate (2 g for Torsades de Pointes)</li><li>Sodium Bicarbonate (8.4%, for hyperkalemia, TCA overdose, prolonged arrest)</li><li>Calcium Gluconate / Calcium Chloride (for hyperkalemia, CCB overdose)</li></ul><h3 id=\"112-bradycardia\">11.2 Bradycardia</h3><ul><li>Atropine (0.5 mg IV, repeat to max 3 mg)</li><li>Transcutaneous Pacing</li><li>Dopamine (5-20 mcg/kg/min)</li><li>Epinephrine (2-10 mcg/min)</li><li>Isoproterenol</li></ul><h3 id=\"113-tachyarrhythmias\">11.3 Tachyarrhythmias</h3><ul><li>Adenosine (6 mg → 12 mg → 12 mg rapid IV push for SVT)</li><li>Esmolol (IV beta-blocker, short-acting)</li><li>Diltiazem IV</li><li>Verapamil IV</li><li>Digoxin</li></ul><h3 id=\"114-shock-vasoactive-agents\">11.4 Shock &amp; Vasoactive Agents</h3><h3 id=\"inopressors\">Inopressors</h3><ul><li>Norepinephrine (first-line for septic shock)</li><li>Epinephrine (anaphylaxis, cardiogenic shock)</li><li>Dopamine (rarely used)</li><li>Phenylephrine (pure vasoconstriction)</li></ul><h3 id=\"inodilators\">Inodilators</h3><ul><li>Dobutamine</li><li>Milrinone</li></ul><ul><li><strong>Vasopressin</strong> (adjunct in septic shock)</li></ul><h3 id=\"115-airway-rapid-sequence-intubation-rsi\">11.5 Airway &amp; Rapid Sequence Intubation (RSI)</h3><h3 id=\"induction-agents\">Induction Agents</h3><ul><li>Etomidate (hemodynamically neutral)</li><li>Ketamine (bronchodilator, preserves BP)</li><li>Propofol (preferred if stable)</li><li>Midazolam</li></ul><h3 id=\"paralytics\">Paralytics</h3><ul><li>Succinylcholine (depolarizing, rapid onset/offset)</li><li>Rocuronium (non-depolarizing, reversed by Sugammadex)</li></ul><h3 id=\"116-toxicology-overdose\">11.6 Toxicology / Overdose</h3><ul><li>Naloxone (Opioid overdose)</li><li>Flumazenil (Benzodiazepine overdose — <em>caution: seizures</em>)</li><li>N-Acetylcysteine (Paracetamol / Acetaminophen overdose)</li><li>Deferoxamine (Iron overdose)</li><li>Digoxin Immune Fab (Digoxin toxicity)</li><li>Lipid Emulsion 20% (Local Anesthetic Toxicity)</li><li>Glucagon (Beta-Blocker Overdose)</li><li>High-Dose Insulin Euglycemia Therapy (CCB/BB Overdose)</li><li>Hydroxocobalamin (Cyanide toxicity)</li></ul><h3 id=\"117-status-epilepticus\">11.7 Status Epilepticus</h3><ul><li>First-Line: Lorazepam IV (0.1 mg/kg)</li><li>Alternative: Midazolam IM / IN</li><li>Second-Line (Urgent Control): Fosphenytoin, Phenytoin, Levetiracetam, Valproate</li><li>Refractory: Midazolam Infusion, Propofol, Pentobarbital / Thiopental</li><li>Pyridoxine (for INH overdose)</li></ul><h3 id=\"118-anaphylaxis\">11.8 Anaphylaxis</h3><ul><li>Epinephrine IM (anterolateral thigh, 0.3-0.5 mg of 1:1000)</li><li>Adjunctive: Diphenhydramine, Ranitidine / Famotidine, Methylprednisolone, Inhaled Albuterol, IV Fluids</li></ul><h3 id=\"119-severe-hyperkalemia\">11.9 Severe Hyperkalemia</h3><ul><li><strong>Membrane Stabilization</strong>: Calcium Gluconate 10% (10 mL) or Calcium Chloride 10% (10 mL)</li><li><strong>Intracellular Shift</strong>: Regular Insulin 10 U + Dextrose 25g (D50W 50 mL), Sodium Bicarbonate (if acidotic), Salbutamol (nebulized 10-20 mg)</li><li><strong>Elimination</strong>: Furosemide (if renal function), Sodium Polystyrene Sulfonate (rarely used), Hemodialysis</li><li><strong>Newer Agents</strong>: Patiromer, Sodium Zirconium Cyclosilicate (Lokelma)</li></ul><h3 id=\"1110-malignant-hyperthermia\">11.10 Malignant Hyperthermia</h3><ul><li>Dantrolene</li></ul><h3 id=\"renal-urological-pharmacology\">RENAL &amp; UROLOGICAL PHARMACOLOGY</h3><h3 id=\"r1-diuretics\">R.1 Diuretics</h3><p><em>(Note: These are also listed under Cardiovascular. This section expands classification by site and mechanism of action in the nephron.)</em></p><p><strong>R.1.1 Osmotic Diuretics</strong> (Site: Proximal Convoluted Tubule, Thin Descending Limb)</p><ul><li>Mannitol</li><li>Glycerin / Glycerol</li><li>Isosorbide</li><li>Urea</li></ul><p><strong>R.1.2 Carbonic Anhydrase Inhibitors</strong> (Site: Proximal Convoluted Tubule)</p><ul><li>Acetazolamide</li><li>Methazolamide</li><li>Dorzolamide (topical, for glaucoma)</li><li>Brinzolamide (topical)</li></ul><p><strong>R.1.3 Loop Diuretics</strong> (Site: Thick Ascending Limb of Loop of Henle; target NKCC2)</p><ul><li>Furosemide</li><li>Bumetanide</li><li>Torsemide</li><li>Ethacrynic Acid (non-sulfonamide)</li></ul><p><strong>R.1.4 Thiazide &amp; Thiazide-Like Diuretics</strong> (Site: Distal Convoluted Tubule; target NCC cotransporter)</p><ul><li>Hydrochlorothiazide (HCTZ)</li><li>Chlorthalidone</li><li>Indapamide</li><li>Metolazone (also acts on proximal tubule)</li><li>Bendroflumethiazide</li><li>Chlorothiazide</li></ul><p><strong>R.1.5 Potassium-Sparing Diuretics</strong> (Site: Collecting Duct)</p><ul><li><em>ENaC Blockers</em>: Amiloride, Triamterene</li><li><em>Aldosterone Antagonists</em>: Spironolactone (non-selective), Eplerenone (selective)</li><li><em>Non-Steroidal Mineralocorticoid Receptor Antagonist (MRA)</em>: Finerenone</li></ul><p><strong>R.1.6 Vasopressin Receptor Antagonists (Vaptans / Aquaretics)</strong> (Site: Collecting Duct; target V2 receptor)</p><ul><li>Tolvaptan (also indicated for ADPKD)</li><li>Conivaptan (IV, V1a/V2 antagonist)</li><li>Mozavaptan</li><li>Satavaptan</li><li>Lixivaptan</li></ul><h3 id=\"r2-antidiuretic-agents-for-diabetes-insipidus-nocturia\">R.2 Antidiuretic Agents (for Diabetes Insipidus &amp; Nocturia)</h3><h3 id=\"r21-vasopressin-analogues\">R.2.1 Vasopressin Analogues</h3><ul><li>Desmopressin / DDAVP (V2-selective agonist; intranasal, oral, IV)</li><li>Terlipressin (V1-selective, for hepatorenal syndrome and variceal bleeding)</li><li>Vasopressin (endogenous hormone; used in septic shock)</li></ul><h3 id=\"r3-agents-for-urinary-retention-bladder-outlet-obstruction\">R.3 Agents for Urinary Retention &amp; Bladder Outlet Obstruction</h3><h3 id=\"r31-alpha-1-adrenergic-antagonists-uroselective\">R.3.1 Alpha-1 Adrenergic Antagonists (Uroselective)</h3><ul><li>Tamsulosin</li><li>Alfuzosin</li><li>Silodosin</li><li>Terazosin (also antihypertensive)</li><li>Doxazosin (also antihypertensive)</li></ul><p><strong>R.3.2 5-Alpha Reductase Inhibitors</strong> (for Benign Prostatic Hyperplasia)</p><ul><li>Finasteride (Type II isoenzyme)</li><li>Dutasteride (Type I &amp; II)</li></ul><p><strong>R.3.3 Phosphodiesterase-5 (PDE-5) Inhibitors</strong> (for BPH ± Erectile Dysfunction)</p><ul><li>Tadalafil (also approved for BPH as once-daily 5 mg)</li></ul><h3 id=\"r4-agents-for-overactive-bladder-oab-urinary-incontinence\">R.4 Agents for Overactive Bladder (OAB) &amp; Urinary Incontinence</h3><h3 id=\"r41-antimuscarinics-anticholinergics\">R.4.1 Antimuscarinics / Anticholinergics</h3><ul><li>Oxybutynin (IR, ER, transdermal patch, gel)</li><li>Tolterodine (IR, ER)</li><li>Solifenacin</li><li>Darifenacin (M3-selective)</li><li>Fesoterodine (prodrug to 5-HMT)</li><li>Trospium Chloride (quaternary amine, minimal CNS penetration)</li><li>Propiverine</li></ul><h3 id=\"r42-beta-3-adrenergic-agonists\">R.4.2 Beta-3 Adrenergic Agonists</h3><ul><li>Mirabegron</li><li>Vibegron</li></ul><h3 id=\"r43-other-agents\">R.4.3 Other Agents</h3><ul><li>OnabotulinumtoxinA (Intradetrusor injections, for refractory OAB/neurogenic detrusor overactivity)</li></ul><h3 id=\"r5-agents-for-erectile-dysfunction-ed\">R.5 Agents for Erectile Dysfunction (ED)</h3><h3 id=\"phosphodiesterase-5-pde-5-inhibitors\">Phosphodiesterase-5 (PDE-5) Inhibitors</h3><ul><li>Sildenafil</li><li>Tadalafil</li><li>Vardenafil</li><li>Avanafil</li></ul><h3 id=\"prostaglandin-e1-alprostadil\">Prostaglandin E1 (Alprostadil)</h3><ul><li>Intracavernosal injection</li><li>Intraurethral pellet</li></ul><h3 id=\"other\">Other</h3><ul><li>Papaverine + Phentolamine (intracavernosal, often combined)</li><li>Yohimbine (obsolete)</li></ul><h3 id=\"r6-agents-for-nephrolithiasis-kidney-stones\">R.6 Agents for Nephrolithiasis (Kidney Stones)</h3><p><strong>R.6.1 Alkalinizing Agents</strong> (for uric acid and cystine stones)</p><ul><li>Potassium Citrate</li><li>Sodium Bicarbonate</li></ul><p><strong>R.6.2 Thiazide Diuretics</strong> (reduce urinary calcium excretion, for idiopathic hypercalciuria)</p><ul><li>Hydrochlorothiazide</li><li>Chlorthalidone</li><li>Indapamide</li></ul><p><strong>R.6.3 Xanthine Oxidase Inhibitors</strong> (for uric acid stones)</p><ul><li>Allopurinol</li><li>Febuxostat</li></ul><p><strong>R.6.4 Chelating Agents</strong> (for cystine stones)</p><ul><li>Tiopronin (Thiola)</li><li>Penicillamine</li></ul><h3 id=\"r65-direct-dissolution-therapy\">R.6.5 Direct Dissolution Therapy</h3><ul><li>Acetylcysteine + Sodium Bicarbonate (for cystine stones, via nephrostomy)</li></ul><h3 id=\"r7-agents-for-chronic-kidney-disease-ckd-renoprotection\">R.7 Agents for Chronic Kidney Disease (CKD) &amp; Renoprotection</h3><p><strong>R.7.1 RAAS Inhibitors</strong> (Renoprotective, reduce proteinuria)</p><ul><li>ACE Inhibitors: Ramipril, Lisinopril, Enalapril, Benazepril</li><li>ARBs: Losartan, Irbesartan, Telmisartan, Candesartan, Valsartan</li></ul><p><strong>R.7.2 SGLT2 Inhibitors</strong> (Renoprotective in CKD with and without diabetes)</p><ul><li>Dapagliflozin</li><li>Empagliflozin</li><li>Canagliflozin</li></ul><p><strong>R.7.3 Non-Steroidal MRAs</strong> (for diabetic kidney disease)</p><ul><li>Finerenone</li></ul><h3 id=\"r74-endothelin-receptor-antagonists\">R.7.4 Endothelin Receptor Antagonists</h3><ul><li>Atrasentan (investigational/specific approvals)</li></ul><p><strong>R.7.5 Phosphate Binders</strong> (for hyperphosphatemia in CKD)</p><ul><li>Calcium-Based: Calcium Carbonate, Calcium Acetate</li><li>Non-Calcium-Based: Sevelamer Carbonate, Sevelamer Hydrochloride, Lanthanum Carbonate</li><li>Iron-Based: Sucroferric Oxyhydroxide, Ferric Citrate</li></ul><p><strong>R.7.6 Vitamin D Receptor Agonists</strong> (for secondary hyperparathyroidism in CKD)</p><ul><li>Calcitriol (1,25-dihydroxyvitamin D3)</li><li>Paricalcitol (synthetic, less calcemic effect)</li><li>Doxercalciferol</li><li>Alfacalcidol</li></ul><p><strong>R.7.7 Calcimimetics</strong> (for secondary hyperparathyroidism in dialysis patients)</p><ul><li>Cinacalcet (PO)</li><li>Etelcalcetide (IV, for hemodialysis)</li><li>Evocalcet</li></ul><p><strong>R.7.8 Erythropoiesis-Stimulating Agents (ESAs)</strong> (for anemia of CKD)</p><ul><li>Epoetin Alfa</li><li>Epoetin Beta</li><li>Darbepoetin Alfa</li><li>Methoxy Polyethylene Glycol-Epoetin Beta (Pegylated)</li><li>Hypoxia-Inducible Factor Prolyl Hydroxylase Inhibitors (HIF-PHI)<ul><li>Roxadustat</li><li>Daprodustat</li><li>Vadadustat</li></ul></li></ul><p><strong>R.7.9 Potassium Binders</strong> (for hyperkalemia in CKD)</p><ul><li>Patiromer (calcium-based polymer)</li><li>Sodium Zirconium Cyclosilicate / SZC (Lokelma)</li><li>Sodium Polystyrene Sulfonate / SPS (Kayexalate, historical, risk of colonic necrosis)</li></ul><p><strong>R.7.10 Alkalinizing Agents</strong> (for metabolic acidosis of CKD)</p><ul><li>Sodium Bicarbonate</li></ul><h3 id=\"r8-agents-for-acute-kidney-injury-aki-critical-care-nephrology\">R.8 Agents for Acute Kidney Injury (AKI) &amp; Critical Care Nephrology</h3><ul><li>Loop Diuretics (Furosemide — for volume management, does not prevent or treat AKI but manages fluid overload)</li><li>Fenoldopam (Dopamine D1 agonist, historically used, no proven benefit)</li><li>Atrial Natriuretic Peptide / ANP (Anaritide, investigational)</li><li>Alkaline Phosphatase (recombinant, investigational for sepsis-associated AKI)</li></ul><h3 id=\"r9-agents-for-renal-tubular-acidosis-rta\">R.9 Agents for Renal Tubular Acidosis (RTA)</h3><ul><li>Sodium Bicarbonate (for Type 1/distal RTA and Type 2/proximal RTA)</li><li>Potassium Citrate (for Type 1 RTA with hypokalemia and nephrolithiasis)</li><li>Thiazide Diuretics (for Type 4 RTA with hyperkalemia, off-label use to enhance potassium excretion by increasing distal sodium delivery)</li></ul><h3 id=\"r10-agents-for-polycystic-kidney-disease-adpkd\">R.10 Agents for Polycystic Kidney Disease (ADPKD)</h3><ul><li>Tolvaptan (Vasopressin V2 Receptor Antagonist, slows cyst growth and renal function decline)</li><li>Somatostatin Analogues (Octreotide, Lanreotide — investigational benefit, specific settings)</li></ul><h3 id=\"r11-urological-analgesics\">R.11 Urological Analgesics</h3><ul><li>Phenazopyridine (Topical analgesic on urinary tract mucosa, for dysuria)</li><li>Dimethyl Sulfoxide / DMSO (Intravesical, for interstitial cystitis)</li></ul><h3 id=\"r12-agents-for-interstitial-cystitis-bladder-pain-syndrome\">R.12 Agents for Interstitial Cystitis / Bladder Pain Syndrome</h3><ul><li>Pentosan Polysulfate Sodium (Elmiron)</li><li>Amitriptyline (TCA)</li><li>Hydroxyzine (Antihistamine)</li><li>Intravesical Heparin ± Lidocaine ± Sodium Bicarbonate</li></ul><h3 id=\"comprehensive-internal-medicine-pharmacology-master-list\">COMPREHENSIVE INTERNAL MEDICINE PHARMACOLOGY MASTER LIST</h3>"},{"معرّف":"1-cardiovascular-drugs","عنوان":"1. CARDIOVASCULAR DRUGS","html":"<h3 id=\"11-renin-angiotensin-aldosterone-system-raas-inhibitors\">1.1 Renin-Angiotensin-Aldosterone System (RAAS) Inhibitors</h3><p><strong>Primary System:</strong> Cardiovascular, Renal</p><p><strong>Clinical Uses:</strong> Hypertension, Heart Failure (HFrEF), Post-Myocardial Infarction, Diabetic Nephropathy, Chronic Kidney Disease with Proteinuria, Stroke Prevention</p><ul><li><strong>ACE Inhibitors</strong> (suffix: &quot;-pril&quot;) — Lisinopril - Enalapril - Ramipril - Captopril - Perindopril - Quinapril - Trandolapril - Benazepril - Fosinopril - Moexipril</li><li><strong>ARBs</strong> (suffix: &quot;-sartan&quot;) — Losartan - Valsartan - Telmisartan - Candesartan - Irbesartan - Olmesartan - Azilsartan - Eprosartan</li><li><strong>ARNI</strong> — Sacubitril/Valsartan</li><li><strong>Direct Renin Inhibitor</strong> — Aliskiren</li></ul><h3 id=\"12-beta-adrenergic-receptor-blockers\">1.2 Beta-Adrenergic Receptor Blockers</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Hypertension, Angina, Heart Failure (HFrEF), Post-MI, Arrhythmias (atrial fibrillation rate control, SVT), Essential Tremor, Migraine Prophylaxis, Hyperthyroidism Symptom Control, Glaucoma (topical), Portal Hypertension</p><ul><li><strong>Cardioselective (β1)</strong> — Metoprolol Succinate - Metoprolol Tartrate - Atenolol - Bisoprolol - Esmolol - Nebivolol - Acebutolol - Betaxolol - Celiprolol</li><li><strong>Non-Selective (β1+β2)</strong> — Propranolol - Carvedilol (also α1) - Labetalol (α1+β) - Nadolol - Sotalol (also Class III antiarrhythmic) - Timolol - Pindolol (ISA) - Penbutolol</li></ul><h3 id=\"13-calcium-channel-blockers-ccbs\">1.3 Calcium Channel Blockers (CCBs)</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Hypertension, Angina, Supraventricular Tachycardia (non-DHP), Raynaud Phenomenon, Subarachnoid Hemorrhage (Nimodipine)</p><ul><li><strong>Dihydropyridines (Vascular)</strong> — Amlodipine - Nifedipine - Felodipine - Nicardipine - Nimodipine - Isradipine - Nisoldipine - Clevidipine</li><li><strong>Non-Dihydropyridines (Cardiac)</strong> — Verapamil - Diltiazem</li></ul><h3 id=\"14-diuretics\">1.4 Diuretics</h3><p><strong>Primary System:</strong> Cardiovascular, Renal</p><p><strong>Clinical Uses:</strong> Hypertension, Heart Failure (volume overload), Edema (cardiac, hepatic, renal), Nephrotic Syndrome, Cirrhosis/Ascites, Hypercalcemia (loop), Nephrolithiasis with Hypercalciuria (thiazide), Diabetes Insipidus (thiazide paradoxical effect), Metabolic Alkalosis (acetazolamide), Altitude Sickness (acetazolamide), Glaucoma (acetazolamide)</p><ul><li><strong>Loop Diuretics (NKCC2)</strong> — Furosemide - Bumetanide - Torsemide - Ethacrynic Acid</li><li><strong>Thiazide &amp; Thiazide-Like (NCC)</strong> — Hydrochlorothiazide - Chlorthalidone - Indapamide - Metolazone - Bendroflumethiazide - Chlorothiazide</li><li><strong>Potassium-Sparing (ENaC/ALD)</strong> — Spironolactone - Eplerenone - Amiloride - Triamterene - Finerenone</li><li><strong>Carbonic Anhydrase Inhibitors (PCT)</strong> — Acetazolamide - Methazolamide</li><li><strong>Osmotic Diuretics</strong> — Mannitol - Glycerin</li><li><strong>Vaptans (Aquaretics, V2)</strong> — Tolvaptan - Conivaptan</li></ul><h3 id=\"15-antiarrhythmics-vaughan-williams-classification\">1.5 Antiarrhythmics (Vaughan-Williams Classification)</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Supraventricular Tachycardia, Atrial Fibrillation/Flutter, Ventricular Tachycardia, Ventricular Fibrillation, Wolff-Parkinson-White Syndrome</p><ul><li><strong>Class IA</strong> — Quinidine - Procainamide - Disopyramide</li><li><strong>Class IB</strong> — Lidocaine - Mexiletine - Phenytoin (also antiepileptic)</li><li><strong>Class IC</strong> — Flecainide - Propafenone - Encainide - Moricizine</li><li><strong>Class II (Beta-Blockers)</strong> — Esmolol - Metoprolol - Propranolol - Sotalol (also III)</li><li><strong>Class III (K+ Channel Blockers)</strong> — Amiodarone - Dronedarone - Sotalol - Dofetilide - Ibutilide - Vernakalant</li><li><strong>Class IV (Non-DHP CCBs)</strong> — Verapamil - Diltiazem</li><li><strong>Miscellaneous</strong> — Adenosine - Digoxin - Magnesium Sulfate - Ivabradine (If blocker)</li></ul><h3 id=\"16-lipid-lowering-antihyperlipidemic-agents\">1.6 Lipid-Lowering / Antihyperlipidemic Agents</h3><p><strong>Primary System:</strong> Cardiovascular, Hepatic</p><p><strong>Clinical Uses:</strong> Primary &amp; Secondary Prevention of Atherosclerotic Cardiovascular Disease (ASCVD), Hypercholesterolemia, Hypertriglyceridemia, Familial Hypercholesterolemia</p><ul><li><strong>Statins (HMG-CoA Reductase Inhibitors, &quot;-statin&quot;)</strong> — Atorvastatin - Rosuvastatin - Simvastatin - Pravastatin - Fluvastatin - Lovastatin - Pitavastatin</li><li><strong>Cholesterol Absorption Inhibitor</strong> — Ezetimibe</li><li><strong>ATP-Citrate Lyase Inhibitor</strong> — Bempedoic Acid</li><li><strong>PCSK9 Inhibitors (Monoclonal Antibodies, &quot;-cumab&quot;)</strong> — Alirocumab - Evolocumab</li><li><strong>PCSK9 Synthesis Inhibitor (siRNA)</strong> — Inclisiran</li><li><strong>Fibrates</strong> — Gemfibrozil - Fenofibrate - Fenofibric Acid - Bezafibrate - Ciprofibrate</li><li><strong>Bile Acid Sequestrants</strong> — Cholestyramine - Colestipol - Colesevelam</li><li><strong>Omega-3 Fatty Acids</strong> — Icosapent Ethyl</li></ul><h3 id=\"niacin-nicotinic-acid\">Niacin / Nicotinic Acid</h3><ul><li><strong>MTP Inhibitor</strong> — Lomitapide</li><li><strong>ApoB Antisense Oligonucleotide</strong> — Mipomersen</li><li><strong>ANGPTL3 Inhibitor</strong> — Evinacumab</li></ul><h3 id=\"17-antianginal-agents\">1.7 Antianginal Agents</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Stable Angina, Acute Coronary Syndrome, Vasospastic Angina</p><ul><li><strong>Nitrates</strong> — Nitroglycerin (GTN) - Isosorbide Mononitrate - Isosorbide Dinitrate</li><li><strong>Late Sodium Current Inhibitor</strong> — Ranolazine</li><li><strong>Fatty Acid Oxidation Inhibitor</strong> — Trimetazidine</li><li><strong>Beta-Blockers, CCBs</strong> (see above)</li></ul><h3 id=\"18-antithrombotic-agents-antiplatelets-anticoagulants\">1.8 Antithrombotic Agents (Antiplatelets &amp; Anticoagulants)</h3><p><strong>Primary System:</strong> Cardiovascular, Hematological</p><p><strong>Clinical Uses:</strong> Acute Coronary Syndrome, Post-PCI/Stent, Atrial Fibrillation Stroke Prevention, Venous Thromboembolism (DVT/PE) Treatment &amp; Prophylaxis, Mechanical Heart Valves, Peripheral Arterial Disease, Ischemic Stroke/TIA, Heparin-Induced Thrombocytopenia (HIT), Antiphospholipid Syndrome</p><h3 id=\"antiplatelets\">Antiplatelets:</h3><ul><li><strong>COX-1 Inhibitor</strong> — Aspirin (Acetylsalicylic Acid)</li><li><strong>P2Y12 Receptor Antagonists</strong> — Clopidogrel - Prasugrel - Ticagrelor - Ticlopidine - Cangrelor (IV)</li><li><strong>GP IIb/IIIa Inhibitors (IV)</strong> — Abciximab - Eptifibatide - Tirofiban</li><li><strong>Phosphodiesterase-3 Inhibitor</strong> — Cilostazol</li><li><strong>Other</strong> — Dipyridamole - Vorapaxar (PAR-1 Antagonist)</li></ul><h3 id=\"anticoagulants\">Anticoagulants:</h3><ul><li><strong>Heparins / Indirect Inhibitors</strong> — Unfractionated Heparin (UFH) - Enoxaparin - Dalteparin - Tinzaparin - Nadroparin - Fondaparinux</li><li><strong>Vitamin K Antagonists</strong> — Warfarin - Acenocoumarol - Phenprocoumon</li><li><strong>Direct Factor Xa Inhibitors (&quot;-xaban&quot;)</strong> — Rivaroxaban - Apixaban - Edoxaban - Betrixaban</li><li><strong>Direct Thrombin Inhibitors (&quot;-gatran&quot;)</strong> — Dabigatran Etexilate - Argatroban (IV) - Bivalirudin (IV) - Desirudin</li></ul><h3 id=\"thrombolytics-fibrinolytics\">Thrombolytics / Fibrinolytics:</h3><ul><li>Alteplase (tPA) - Tenecteplase (TNK) - Reteplase - Streptokinase - Urokinase</li></ul><h3 id=\"antifibrinolytics\">Antifibrinolytics:</h3><ul><li>Tranexamic Acid (TXA) - Aminocaproic Acid (EACA)</li></ul><h3 id=\"reversal-agents\">Reversal Agents:</h3><ul><li>Protamine Sulfate (Heparin) - Vitamin K (Warfarin) - Idarucizumab (Dabigatran) - Andexanet Alfa (Xa Inhibitors) - 4-Factor PCC</li></ul><h3 id=\"19-vasopressors-inotropes\">1.9 Vasopressors &amp; Inotropes</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Septic Shock, Cardiogenic Shock, Anaphylactic Shock, Neurogenic Shock, Acute Decompensated Heart Failure</p><ul><li><strong>Inopressors</strong> — Norepinephrine - Epinephrine (Adrenaline) - Dopamine - Phenylephrine</li><li><strong>Inodilators</strong> — Dobutamine - Milrinone</li><li><strong>Other Vasopressors</strong> — Vasopressin - Angiotensin II</li><li><strong>Calcium Sensitizer</strong> — Levosimendan</li></ul><h3 id=\"110-heart-failure-specific-agents\">1.10 Heart Failure Specific Agents</h3><p><strong>Primary System:</strong> Cardiovascular</p><p><strong>Clinical Uses:</strong> Chronic Heart Failure (HFrEF/HFpEF)</p><ul><li><strong>Cardiac Glycosides</strong> — Digoxin - Digitoxin</li><li><strong>Soluble Guanylate Cyclase (sGC) Stimulator</strong> — Vericiguat</li></ul>"},{"معرّف":"2-respiratory-drugs","عنوان":"2. RESPIRATORY DRUGS","html":"<h3 id=\"21-bronchodilators\">2.1 Bronchodilators</h3><p><strong>Primary System:</strong> Respiratory</p><p><strong>Clinical Uses:</strong> Asthma, COPD, Bronchospasm, Exercise-Induced Bronchoconstriction</p><ul><li><strong>SABA (Short-Acting Beta-2 Agonists)</strong> — Albuterol/Salbutamol - Levalbuterol - Terbutaline - Pirbuterol</li><li><strong>LABA (Long-Acting Beta-2 Agonists)</strong> — Salmeterol - Formoterol - Vilanterol - Olodaterol - Indacaterol</li><li><strong>SAMA (Short-Acting Muscarinic Antagonists)</strong> — Ipratropium Bromide - Oxitropium</li><li><strong>LAMA (Long-Acting Muscarinic Antagonists)</strong> — Tiotropium - Umeclidinium - Glycopyrronium/Glycopyrrolate - Aclidinium - Revefenacin</li></ul><h3 id=\"22-inhaled-corticosteroids-ics\">2.2 Inhaled Corticosteroids (ICS)</h3><p><strong>Primary System:</strong> Respiratory</p><p><strong>Clinical Uses:</strong> Asthma, COPD (with LABA/LAMA), Eosinophilic Bronchitis</p><ul><li>Fluticasone Propionate - Fluticasone Furoate - Budesonide - Beclomethasone Dipropionate - Mometasone Furoate - Ciclesonide</li></ul><h3 id=\"23-combination-inhalers\">2.3 Combination Inhalers</h3><p><strong>Primary System:</strong> Respiratory</p><p><strong>Clinical Uses:</strong> Asthma, COPD</p><ul><li><strong>ICS + LABA</strong> — Fluticasone Propionate/Salmeterol - Fluticasone Furoate/Vilanterol - Budesonide/Formoterol - Beclomethasone/Formoterol - Mometasone/Formoterol</li><li><strong>LABA + LAMA</strong> — Vilanterol/Umeclidinium - Formoterol/Glycopyrronium - Olodaterol/Tiotropium - Indacaterol/Glycopyrronium</li><li><strong>ICS + LABA + LAMA (Triple)</strong> — Fluticasone Furoate/Vilanterol/Umeclidinium - Budesonide/Formoterol/Glycopyrronium - Beclomethasone/Formoterol/Glycopyrronium</li></ul><h3 id=\"24-leukotriene-modifiers\">2.4 Leukotriene Modifiers</h3><p><strong>Primary System:</strong> Respiratory</p><p><strong>Clinical Uses:</strong> Asthma, Allergic Rhinitis, Exercise-Induced Bronchoconstriction, Aspirin-Exacerbated Respiratory Disease (AERD)</p><ul><li><strong>LTRA</strong> — Montelukast - Zafirlukast</li><li><strong>5-Lipoxygenase Inhibitor</strong> — Zileuton</li></ul><h3 id=\"25-mast-cell-stabilizers\">2.5 Mast Cell Stabilizers</h3><p><strong>Primary System:</strong> Respiratory, Ophthalmic</p><p><strong>Clinical Uses:</strong> Asthma Prophylaxis, Allergic Conjunctivitis</p><ul><li>Cromolyn Sodium - Nedocromil</li></ul><h3 id=\"26-methylxanthines\">2.6 Methylxanthines</h3><p><strong>Primary System:</strong> Respiratory, CNS</p><p><strong>Clinical Uses:</strong> Severe COPD, Severe Asthma (adjunctive), Apnea of Prematurity (Caffeine)</p><ul><li>Theophylline - Aminophylline - Doxofylline</li></ul><h3 id=\"27-phosphodiesterase-4-pde-4-inhibitors\">2.7 Phosphodiesterase-4 (PDE-4) Inhibitors</h3><p><strong>Primary System:</strong> Respiratory, Rheumatological</p><p><strong>Clinical Uses:</strong> Severe COPD with Chronic Bronchitis &amp; Frequent Exacerbations, Psoriatic Arthritis (Apremilast)</p><ul><li>Roflumilast - Apremilast</li></ul><h3 id=\"28-monoclonal-antibodies-for-severe-asthma\">2.8 Monoclonal Antibodies for Severe Asthma</h3><p><strong>Primary System:</strong> Respiratory, Immunological</p><p><strong>Clinical Uses:</strong> Severe Eosinophilic Asthma, Allergic Asthma, Aspirin-Exacerbated Respiratory Disease, Eosinophilic Granulomatosis with Polyangiitis (EGPA)</p><ul><li>Omalizumab (anti-IgE) - Mepolizumab (anti-IL-5) - Reslizumab (anti-IL-5) - Benralizumab (anti-IL-5R) - Dupilumab (anti-IL-4Rα) - Tezepelumab (anti-TSLP)</li></ul><h3 id=\"29-cough-cold-preparations\">2.9 Cough &amp; Cold Preparations</h3><p><strong>Primary System:</strong> Respiratory</p><ul><li><strong>Antitussives (Central)</strong> — Dextromethorphan - Codeine - Butamirate</li><li><strong>Antitussive (Peripheral)</strong> — Benzonatate</li><li><strong>Expectorant</strong> — Guaifenesin</li><li><strong>Mucolytics</strong> — Acetylcysteine (NAC) - Carbocisteine - Erdosteine - Bromhexine - Ambroxol</li></ul>"},{"معرّف":"3-gastrointestinal-hepatobiliary-drugs","عنوان":"3. GASTROINTESTINAL & HEPATOBILIARY DRUGS","html":"<h3 id=\"31-acid-suppressive-therapy\">3.1 Acid-Suppressive Therapy</h3><p><strong>Primary System:</strong> Gastrointestinal</p><p><strong>Clinical Uses:</strong> Gastroesophageal Reflux Disease (GERD), Peptic Ulcer Disease, Dyspepsia, Zollinger-Ellison Syndrome, H. pylori Eradication (adjunct), Stress Ulcer Prophylaxis, NSAID-Induced Gastropathy Prevention</p><ul><li><strong>PPIs (&quot;-prazole&quot;)</strong> — Omeprazole - Esomeprazole - Lansoprazole - Pantoprazole - Rabeprazole - Dexlansoprazole</li><li><strong>H2RAs (&quot;-tidine&quot;)</strong> — Famotidine - Nizatidine - Cimetidine</li></ul><h3 id=\"32-prokinetic-agents\">3.2 Prokinetic Agents</h3><p><strong>Primary System:</strong> Gastrointestinal</p><p><strong>Clinical Uses:</strong> Gastroparesis, GERD (refractory), Nausea/Vomiting</p><ul><li>Metoclopramide - Domperidone - Erythromycin (low dose) - Prucalopride (5-HT4 agonist, for constipation)</li></ul><h3 id=\"33-antiemetics\">3.3 Antiemetics</h3><p><strong>Primary System:</strong> Gastrointestinal, CNS (Vomiting Center, Chemoreceptor Trigger Zone)</p><p><strong>Clinical Uses:</strong> Chemotherapy-Induced Nausea &amp; Vomiting (CINV), Postoperative Nausea &amp; Vomiting (PONV), Gastroenteritis, Motion Sickness, Vertigo, Migraine-Associated Nausea, Hyperemesis Gravidarum</p><ul><li><strong>5-HT3 Antagonists (&quot;-setron&quot;)</strong> — Ondansetron - Granisetron - Palonosetron - Dolasetron</li><li><strong>Dopamine D2 Antagonists</strong> — Prochlorperazine - Promethazine - Metoclopramide - Droperidol - Haloperidol</li><li><strong>NK1 Antagonists (&quot;-pitant&quot;)</strong> — Aprepitant - Fosaprepitant - Netupitant - Rolapitant</li><li><strong>Antihistamines (Motion Sickness)</strong> — Dimenhydrinate - Meclizine - Cyclizine - Hydroxyzine - Cinnarizine</li><li><strong>Anticholinergic</strong> — Scopolamine/Hyoscine (Transdermal Patch)</li><li><strong>Corticosteroid</strong> — Dexamethasone</li><li><strong>Cannabinoids</strong> — Dronabinol - Nabilone</li><li><strong>Benzodiazepine</strong> — Lorazepam (anticipatory nausea)</li></ul><h3 id=\"34-antidiarrheals\">3.4 Antidiarrheals</h3><p><strong>Primary System:</strong> Gastrointestinal</p><p><strong>Clinical Uses:</strong> Acute Non-Infectious Diarrhea, Traveler&#39;s Diarrhea, Chronic Diarrhea (IBS-D, Bile Acid Diarrhea), High-Output Ileostomy, Carcinoid Syndrome</p><ul><li><strong>μ-Opioid Agonists (Peripheral)</strong> — Loperamide - Diphenoxylate + Atropine (Lomotil)</li><li><strong>Bile Acid Sequestrants</strong> — Cholestyramine - Colestipol - Colesevelam</li><li><strong>Somatostatin Analog</strong> — Octreotide</li><li><strong>Enkephalinase Inhibitor</strong> — Racecadotril</li><li><strong>Adsorbent</strong> — Bismuth Subsalicylate</li></ul><h3 id=\"35-laxatives\">3.5 Laxatives</h3><p><strong>Primary System:</strong> Gastrointestinal</p><p><strong>Clinical Uses:</strong> Constipation (Functional, Opioid-Induced, IBS-C), Bowel Preparation, Hepatic Encephalopathy (Lactulose)</p><ul><li><strong>Bulk-Forming</strong> — Psyllium - Methylcellulose - Polycarbophil</li><li><strong>Osmotic</strong> — Polyethylene Glycol (PEG 3350) - Lactulose - Magnesium Citrate - Magnesium Hydroxide (Milk of Magnesia)</li><li><strong>Stimulant</strong> — Bisacodyl - Senna - Sodium Picosulfate</li><li><strong>Stool Softeners</strong> — Docusate Sodium</li><li><strong>Chloride Channel Activator</strong> — Lubiprostone</li><li><strong>Guanylate Cyclase-C Agonists</strong> — Linaclotide - Plecanatide</li><li><strong>Peripheral Opioid Antagonists (PAMORAs)</strong> — Naloxegol - Methylnaltrexone - Naldemedine</li></ul><h3 id=\"36-inflammatory-bowel-disease-ibd-therapy\">3.6 Inflammatory Bowel Disease (IBD) Therapy</h3><p><strong>Primary System:</strong> Gastrointestinal, Immunological</p><p><strong>Clinical Uses:</strong> Crohn&#39;s Disease, Ulcerative Colitis, Pouchitis, Microscopic Colitis</p><ul><li><strong>5-Aminosalicylates (5-ASA)</strong> — Mesalamine/Mesalazine - Sulfasalazine - Olsalazine - Balsalazide</li><li><strong>Immunomodulators</strong> — Azathioprine - 6-Mercaptopurine - Methotrexate - Cyclosporine (severe UC)</li><li><strong>TNF Inhibitors</strong> — Infliximab - Adalimumab - Golimumab - Certolizumab Pegol</li><li><strong>Anti-Integrin</strong> — Vedolizumab (α4β7) - Natalizumab (α4)</li><li><strong>Anti-IL-12/23</strong> — Ustekinumab</li><li><strong>Anti-IL-23</strong> — Risankizumab - Guselkumab</li><li><strong>JAK Inhibitors</strong> — Tofacitinib - Upadacitinib - Filgotinib</li><li><strong>S1P Receptor Modulator</strong> — Ozanimod</li></ul><h3 id=\"37-hepatobiliary-drugs\">3.7 Hepatobiliary Drugs</h3><p><strong>Primary System:</strong> Hepatic, Gastrointestinal</p><p><strong>Clinical Uses:</strong> Primary Biliary Cholangitis (PBC), Primary Sclerosing Cholangitis, Portal Hypertension/Varices, Hepatic Encephalopathy, Hepatorenal Syndrome (HRS), Wilson Disease, Non-Alcoholic Fatty Liver Disease / MASH</p><ul><li><strong>Ursodeoxycholic Acid (UDCA)</strong> — First-line for PBC</li><li><strong>Obeticholic Acid (FXR Agonist)</strong> — PBC (second-line)</li><li><strong>Fibrates</strong> — Bezafibrate - Fenofibrate (adjunct in PBC)</li><li><strong>Non-Selective Beta-Blockers (Portal Hypertension)</strong> — Propranolol - Nadolol - Carvedilol</li><li><strong>Vasopressin Analogue (Variceal Bleed/HRS)</strong> — Terlipressin</li><li><strong>Somatostatin Analogue (Variceal Bleed)</strong> — Octreotide</li><li><strong>Rifaximin (Non-Absorbable Antibiotic)</strong> — Hepatic Encephalopathy</li><li><strong>Lactulose (Osmotic Laxative)</strong> — Hepatic Encephalopathy</li><li><strong>Albumin (IV)</strong> — Spontaneous Bacterial Peritonitis (SBP) Prevention of HRS, Volume Resuscitation Post Large-Volume Paracentesis</li><li><strong>Chelating Agents (Wilson Disease)</strong> — Penicillamine - Trientine - Zinc Acetate</li><li><strong>PPAR Agonist (MASH)</strong> — Pioglitazone (off-label)</li><li><strong>Thyroid Hormone Receptor Beta Agonist (MASH)</strong> — Resmetirom</li></ul>"},{"معرّف":"4-endocrinology-metabolism-drugs","عنوان":"4. ENDOCRINOLOGY & METABOLISM DRUGS","html":"<h3 id=\"41-diabetes-mellitus\">4.1 Diabetes Mellitus</h3><p><strong>Primary System:</strong> Endocrine (Pancreas), Multi-system (Kidney, CV, Liver, Adipose)</p><p><strong>Clinical Uses:</strong> Type 1 Diabetes, Type 2 Diabetes, Gestational Diabetes, Prevention of CV &amp; Renal Events in Diabetes</p><ul><li><strong>Insulins (Rapid)</strong> — Lispro - Aspart - Glulisine - Faster Aspart</li><li><strong>Insulins (Short)</strong> — Regular Human Insulin</li><li><strong>Insulins (Intermediate)</strong> — NPH / Isophane</li><li><strong>Insulins (Long/Basal)</strong> — Glargine U-100 - Glargine U-300 - Detemir - Degludec</li><li><strong>Biguanide</strong> — Metformin</li><li><strong>Sulfonylureas</strong> — Glibenclamide/Glyburide - Glipizide - Gliclazide - Glimepiride</li><li><strong>Meglitinides</strong> — Repaglinide - Nateglinide</li><li><strong>Thiazolidinediones (TZDs)</strong> — Pioglitazone - Rosiglitazone</li><li><strong>Alpha-Glucosidase Inhibitors</strong> — Acarbose - Miglitol - Voglibose</li><li><strong>DPP-4 Inhibitors (&quot;-gliptin&quot;)</strong> — Sitagliptin - Linagliptin - Saxagliptin - Alogliptin - Vildagliptin</li><li><strong>GLP-1 Receptor Agonists</strong> — Liraglutide - Dulaglutide - Semaglutide (SC + PO) - Exenatide (SC) - Lixisenatide - Tirzepatide (GIP/GLP-1 dual)</li><li><strong>SGLT2 Inhibitors (&quot;-gliflozin&quot;)</strong> — Empagliflozin - Dapagliflozin - Canagliflozin - Ertugliflozin</li><li><strong>Amylin Analog</strong> — Pramlintide</li></ul><h3 id=\"42-thyroid\">4.2 Thyroid</h3><p><strong>Primary System:</strong> Endocrine (Thyroid)</p><p><strong>Clinical Uses:</strong> Hypothyroidism, Myxedema Coma, Hyperthyroidism/Graves Disease, Thyroid Storm</p><ul><li><strong>Replacement</strong> — Levothyroxine (T4) - Liothyronine (T3) - Desiccated Thyroid Extract</li><li><strong>Thionamides (Anti-thyroid)</strong> — Methimazole - Carbimazole - Propylthiouracil (PTU)</li><li><strong>Iodine Preparations</strong> — Lugol&#39;s Solution - SSKI (Potassium Iodide)</li><li><strong>Beta-Blockers (Symptom Control)</strong> — Propranolol</li></ul><h3 id=\"43-corticosteroids\">4.3 Corticosteroids</h3><p><strong>Primary System:</strong> Endocrine (Adrenal), Immunological, Multi-system</p><p><strong>Clinical Uses:</strong> Adrenal Insufficiency (Addison Disease), Congenital Adrenal Hyperplasia, Inflammatory &amp; Autoimmune Conditions (Asthma, IBD, SLE, Vasculitis, Rheumatoid Arthritis, Gout Flare, Multiple Sclerosis Relapse, Allergic Reactions, Anaphylaxis), Chemotherapy Protocols, Cerebral Edema, COVID-19 (severe), Pneumocystis Pneumonia (adjunct), Septic Shock (refractory), Organ Transplantation, Prevention of RDS (antenatal)</p><ul><li><strong>Short-Acting</strong> — Hydrocortisone</li><li><strong>Intermediate-Acting</strong> — Prednisone - Prednisolone - Methylprednisolone - Triamcinolone</li><li><strong>Long-Acting</strong> — Dexamethasone - Betamethasone</li><li><strong>Mineralocorticoid</strong> — Fludrocortisone</li></ul><h3 id=\"44-calcium-homeostasis-bone-metabolism\">4.4 Calcium Homeostasis &amp; Bone Metabolism</h3><p><strong>Primary System:</strong> Endocrine (Parathyroid, Bone), Renal</p><p><strong>Clinical Uses:</strong> Osteoporosis, Osteomalacia, Hypocalcemia, Hypercalcemia of Malignancy, Paget Disease of Bone, Hypoparathyroidism, Vitamin D Deficiency</p><ul><li><strong>Bisphosphonates</strong> — Alendronate - Risedronate - Zoledronic Acid - Pamidronate - Ibandronate</li><li><strong>RANKL Inhibitor</strong> — Denosumab</li><li><strong>Anabolic Agents</strong> — Teriparatide (PTH 1-34) - Abaloparatide</li><li><strong>Sclerostin Inhibitor</strong> — Romosozumab</li><li><strong>SERM</strong> — Raloxifene</li><li><strong>Calcitonin</strong> — Salmon Calcitonin</li><li><strong>Vitamin D3</strong> — Cholecalciferol</li><li><strong>Vitamin D2</strong> — Ergocalciferol</li><li><strong>Active Vitamin D</strong> — Calcitriol - Alfacalcidol - Paricalcitol - Doxercalciferol</li><li><strong>Calcium Salts</strong> — Calcium Carbonate - Calcium Citrate - Calcium Gluconate (IV)</li><li><strong>Calcimimetic</strong> — Cinacalcet - Etelcalcetide (IV)</li></ul><h3 id=\"cinacalcet-for-primary-hyperparathyroidism-non-surgical\">Cinacalcet for Primary Hyperparathyroidism (non-surgical)</h3><h3 id=\"45-pituitary-hypothalamic-hormones\">4.5 Pituitary &amp; Hypothalamic Hormones</h3><p><strong>Primary System:</strong> Endocrine (Pituitary, Hypothalamus)</p><p><strong>Clinical Uses:</strong> Growth Hormone Deficiency, Acromegaly, Central Diabetes Insipidus, SIADH, Prolactinoma, Central Precocious Puberty, Infertility</p><ul><li><strong>GH</strong> — Somatropin</li><li><strong>Somatostatin Analogs (Acromegaly)</strong> — Octreotide - Lanreotide - Pasireotide</li><li><strong>GH Receptor Antagonist</strong> — Pegvisomant</li><li><strong>Dopamine Agonists (Prolactinoma)</strong> — Cabergoline - Bromocriptine</li><li><strong>GnRH Agonists</strong> — Leuprolide - Goserelin - Triptorelin</li><li><strong>GnRH Antagonists</strong> — Degarelix - Cetrorelix</li></ul><h3 id=\"desmopressin-v2-agonist-diabetes-insipidusnocturia\">Desmopressin (V2 Agonist, Diabetes Insipidus/Nocturia)</h3><ul><li><strong>Vasopressin Antagonist (SIADH)</strong> — Tolvaptan</li></ul>"},{"معرّف":"5-renal-urological-drugs","عنوان":"5. RENAL & UROLOGICAL DRUGS","html":"<h3 id=\"51-renoprotective-agents-ckd\">5.1 Renoprotective Agents (CKD)</h3><p><strong>Primary System:</strong> Renal, Cardiovascular</p><p><strong>Clinical Uses:</strong> Chronic Kidney Disease, Diabetic Nephropathy, Proteinuric Kidney Disease</p><ul><li>ACE Inhibitors - ARBs - SGLT2 Inhibitors - Finerenone</li></ul><h3 id=\"52-phosphate-binders-ckd-mbd\">5.2 Phosphate Binders (CKD-MBD)</h3><p><strong>Primary System:</strong> Renal, Endocrine</p><p><strong>Clinical Uses:</strong> Hyperphosphatemia in CKD Stage 4-5 &amp; Dialysis</p><ul><li><strong>Calcium-Based</strong> — Calcium Carbonate - Calcium Acetate</li><li><strong>Non-Calcium-Based</strong> — Sevelamer Carbonate - Lanthanum Carbonate - Sucroferric Oxyhydroxide - Ferric Citrate</li></ul><h3 id=\"53-potassium-binders\">5.3 Potassium Binders</h3><p><strong>Primary System:</strong> Renal, Cardiovascular (Emergency)</p><p><strong>Clinical Uses:</strong> Acute &amp; Chronic Hyperkalemia</p><ul><li>Patiromer - Sodium Zirconium Cyclosilicate (SZC/Lokelma) - Sodium Polystyrene Sulfonate (SPS, historical)</li></ul><h3 id=\"54-erythropoiesis-stimulating-agents-esas\">5.4 Erythropoiesis-Stimulating Agents (ESAs)</h3><p><strong>Primary System:</strong> Renal, Hematological</p><p><strong>Clinical Uses:</strong> Anemia of Chronic Kidney Disease</p><ul><li>Epoetin Alfa - Darbepoetin Alfa - Methoxy PEG-Epoetin Beta</li><li><strong>HIF-PH Inhibitors</strong> — Roxadustat - Daprodustat - Vadadustat</li></ul><h3 id=\"55-agents-for-benign-prostatic-hyperplasia-bph-overactive-bladder-oab\">5.5 Agents for Benign Prostatic Hyperplasia (BPH) &amp; Overactive Bladder (OAB)</h3><p><strong>Primary System:</strong> Urological</p><p><strong>Clinical Uses:</strong> BPH/LUTS, Urinary Retention, Overactive Bladder, Urge Incontinence, Nocturia</p><ul><li><strong>Alpha-1 Blockers (Uroselective)</strong> — Tamsulosin - Alfuzosin - Silodosin</li><li><strong>5-Alpha Reductase Inhibitors</strong> — Finasteride - Dutasteride</li><li><strong>PDE-5 Inhibitor (BPH)</strong> — Tadalafil 5 mg once daily</li><li><strong>Antimuscarinics (OAB)</strong> — Oxybutynin - Tolterodine - Solifenacin - Darifenacin - Fesoterodine - Trospium - Propiverine</li><li><strong>Beta-3 Agonists (OAB)</strong> — Mirabegron - Vibegron</li></ul><h3 id=\"intradetrusor-botulinum-toxin-refractory-oab\">Intradetrusor Botulinum Toxin (Refractory OAB)</h3><h3 id=\"56-agents-for-polycystic-kidney-disease-adpkd\">5.6 Agents for Polycystic Kidney Disease (ADPKD)</h3><p><strong>Primary System:</strong> Renal</p><p><strong>Clinical Use:</strong> ADPKD to slow cyst growth and decline in eGFR</p><ul><li>Tolvaptan</li></ul><h3 id=\"57-agents-for-nephrolithiasis\">5.7 Agents for Nephrolithiasis</h3><p><strong>Primary System:</strong> Renal, Urological</p><p><strong>Clinical Uses:</strong> Uric Acid Stones, Calcium Oxalate Stones (Hypercalciuria), Cystine Stones</p><ul><li>Potassium Citrate - Thiazide Diuretics - Allopurinol - Tiopronin - Penicillamine</li></ul>"},{"معرّف":"6-hematological-drugs","عنوان":"6. HEMATOLOGICAL DRUGS","html":"<h3 id=\"61-antithrombotics\">6.1 Antithrombotics</h3><p><em>(See Section 1.8 — all agents are cross-listed)</em></p><p><strong>Primary Systems:</strong> Cardiovascular, Hematological</p><h3 id=\"62-hematopoietic-growth-factors\">6.2 Hematopoietic Growth Factors</h3><p><strong>Primary System:</strong> Hematological</p><p><strong>Clinical Uses:</strong> Chemotherapy-Induced Neutropenia, Anemia of CKD, Aplastic Anemia, Bone Marrow Transplant</p><ul><li><strong>G-CSF</strong> — Filgrastim - Pegfilgrastim</li><li><strong>GM-CSF</strong> — Sargramostim</li><li><strong>Erythropoietin</strong> — Epoetin Alfa - Darbepoetin Alfa</li><li><strong>Thrombopoietin Receptor Agonists</strong> — Romiplostim - Eltrombopag - Avatrombopag</li><li><strong>Erythroid Maturation Agent</strong> — Luspatercept (for MDS/beta-thalassemia)</li></ul><h3 id=\"63-iron-vitamin-b12-and-folate\">6.3 Iron, Vitamin B12, and Folate</h3><p><strong>Primary System:</strong> Hematological</p><p><strong>Clinical Uses:</strong> Iron Deficiency Anemia, Vitamin B12 Deficiency (Pernicious Anemia, Dietary), Folate Deficiency, Methotrexate Rescue</p><ul><li><strong>Oral Iron</strong> — Ferrous Sulfate - Ferrous Gluconate - Ferrous Fumarate</li><li><strong>IV Iron</strong> — Iron Sucrose - Ferric Carboxymaltose - Iron Dextran - Ferumoxytol - Iron Isomaltoside</li><li><strong>Vitamin B12</strong> — Cyanocobalamin - Hydroxocobalamin</li><li><strong>Folate</strong> — Folic Acid - Leucovorin/Folinic Acid (Rescue)</li></ul><h3 id=\"64-antifibrinolytics\">6.4 Antifibrinolytics</h3><ul><li>Tranexamic Acid - Aminocaproic Acid</li></ul>"},{"معرّف":"7-rheumatology-immunomodulatory-drugs","عنوان":"7. RHEUMATOLOGY & IMMUNOMODULATORY DRUGS","html":"<h3 id=\"71-non-steroidal-anti-inflammatory-drugs-nsaids\">7.1 Non-Steroidal Anti-Inflammatory Drugs (NSAIDs)</h3><p><strong>Primary System:</strong> Musculoskeletal, Multi-system</p><p><strong>Clinical Uses:</strong> Pain, Inflammation, Osteoarthritis, Rheumatoid Arthritis, Gout Flare, Ankylosing Spondylitis, Dysmenorrhea, Pericarditis, Patent Ductus Arteriosus (Indomethacin)</p><ul><li><strong>Non-Selective COX Inhibitors</strong> — Ibuprofen - Naproxen - Diclofenac - Indomethacin - Ketorolac - Meloxicam</li><li><strong>COX-2 Selective (Coxibs)</strong> — Celecoxib - Etoricoxib - Parecoxib (IV)</li></ul><h3 id=\"72-disease-modifying-antirheumatic-drugs-dmards\">7.2 Disease-Modifying Antirheumatic Drugs (DMARDs)</h3><p><strong>Primary System:</strong> Rheumatological, Immunological</p><p><strong>Clinical Uses:</strong> Rheumatoid Arthritis, Psoriatic Arthritis, Ankylosing Spondylitis, Systemic Lupus Erythematosus, Vasculitis, Inflammatory Myopathies</p><ul><li><strong>Conventional Synthetic (csDMARDs)</strong> — Methotrexate - Leflunomide - Sulfasalazine - Hydroxychloroquine</li><li><strong>Biologics (bDMARDs - TNFi)</strong> — Infliximab - Adalimumab - Etanercept - Golimumab - Certolizumab Pegol</li><li><strong>Biologics (Non-TNF)</strong> — Tocilizumab (anti-IL-6R) - Sarilumab (anti-IL-6R) - Anakinra (IL-1RA) - Rituximab (anti-CD20) - Abatacept (CTLA4-Ig) - Belimumab (anti-BLyS, for SLE)</li><li><strong>Targeted Synthetic (tsDMARDs - JAK Inhibitors)</strong> — Tofacitinib - Baricitinib - Upadacitinib - Filgotinib</li></ul><h3 id=\"73-gout-hyperuricemia\">7.3 Gout &amp; Hyperuricemia</h3><p><strong>Primary System:</strong> Rheumatological, Renal</p><p><strong>Clinical Uses:</strong> Acute Gout Flare, Chronic Gout, Uric Acid Nephrolithiasis, Tumor Lysis Syndrome Prophylaxis</p><ul><li><strong>Acute Flare</strong> — NSAIDs - Colchicine - Corticosteroids (Prednisone, Intra-articular Triamcinolone)</li><li><strong>Urate-Lowering Therapy (Xanthine Oxidase Inhibitors)</strong> — Allopurinol - Febuxostat</li><li><strong>Uricosuric</strong> — Probenecid</li><li><strong>Recombinant Uricase</strong> — Pegloticase - Rasburicase (for Tumor Lysis Syndrome)</li></ul>"},{"معرّف":"8-central-nervous-system-cns-drugs","عنوان":"8. CENTRAL NERVOUS SYSTEM (CNS) DRUGS","html":"<h3 id=\"81-antidepressants\">8.1 Antidepressants</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Major Depressive Disorder, Generalized Anxiety Disorder, Panic Disorder, OCD, PTSD, Social Anxiety Disorder, Neuropathic Pain, Fibromyalgia, Chronic Pain, Smoking Cessation (Bupropion), Premenstrual Dysphoric Disorder</p><ul><li><strong>SSRIs</strong> — Fluoxetine - Sertraline - Paroxetine - Citalopram - Escitalopram - Fluvoxamine</li><li><strong>SNRIs</strong> — Venlafaxine - Desvenlafaxine - Duloxetine - Levomilnacipran - Milnacipran</li><li><strong>TCAs</strong> — Amitriptyline - Nortriptyline - Imipramine - Desipramine - Clomipramine - Doxepin</li><li><strong>Atypical</strong> — Mirtazapine - Trazodone - Bupropion - Vilazodone - Vortioxetine - Agomelatine</li><li><strong>MAOIs</strong> — Phenelzine - Tranylcypromine - Selegiline</li><li><strong>NMDA Antagonist (TRD)</strong> — Esketamine (Intranasal)</li></ul><h3 id=\"82-antipsychotics\">8.2 Antipsychotics</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Schizophrenia, Schizoaffective Disorder, Bipolar Disorder (Mania, Maintenance), Acute Agitation/Psychosis, Tourette Syndrome, Intractable Hiccups (Chlorpromazine), Adjunct in Severe Depression</p><ul><li><strong>First-Generation (Typical)</strong> — Haloperidol - Chlorpromazine - Fluphenazine - Perphenazine - Loxapine</li><li><strong>Second-Generation (Atypical)</strong> — Risperidone - Paliperidone - Olanzapine - Quetiapine - Clozapine - Aripiprazole - Brexpiprazole - Cariprazine - Lurasidone - Ziprasidone - Asenapine - Iloperidone</li><li><strong>Long-Acting Injectables (LAIs)</strong> — All the above with LAI formulations (Risperidone Consta, Paliperidone Palmitate, Aripiprazole LAI, etc.)</li></ul><h3 id=\"83-mood-stabilizers\">8.3 Mood Stabilizers</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Bipolar Disorder (Acute Mania, Maintenance), Schizoaffective Disorder, Adjunctive in Refractory Major Depression</p><ul><li>Lithium - Valproic Acid/Divalproex - Carbamazepine - Oxcarbazepine - Lamotrigine</li></ul><h3 id=\"84-anxiolytics-sedative-hypnotics\">8.4 Anxiolytics &amp; Sedative-Hypnotics</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Anxiety Disorders, Panic Attacks, Insomnia, Alcohol Withdrawal, Seizures (Acute), Procedural Sedation, Muscle Spasms</p><ul><li><strong>Benzodiazepines</strong> — Diazepam - Lorazepam - Midazolam - Alprazolam - Clonazepam - Chlordiazepoxide - Temazepam - Triazolam - Clorazepate</li><li><strong>Z-Drugs (Hypnotics)</strong> — Zolpidem - Zopiclone - Eszopiclone - Zaleplon</li><li><strong>Barbiturates</strong> — Phenobarbital - Butalbital - Thiopental</li><li><strong>Melatonin Agonist</strong> — Ramelteon</li><li><strong>Orexin Antagonists</strong> — Suvorexant - Lemborexant - Daridorexant</li></ul><h3 id=\"buspirone-5-ht1a-partial-agonist\">Buspirone (5-HT1A Partial Agonist)</h3><h3 id=\"85-antiepileptics-anticonvulsants\">8.5 Antiepileptics (Anticonvulsants)</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Focal &amp; Generalized Epilepsy, Status Epilepticus, Neuropathic Pain (Gabapentin, Pregabalin, Carbamazepine), Fibromyalgia, Migraine Prophylaxis (Topiramate, Valproate), Bipolar Disorder (Valproate, Lamotrigine, Carbamazepine), Essential Tremor</p><ul><li><strong>First Generation</strong> — Phenytoin - Fosphenytoin - Phenobarbital - Carbamazepine - Valproate - Ethosuximide</li><li><strong>Second/Third Generation</strong> — Lamotrigine - Topiramate - Levetiracetam - Brivaracetam - Gabapentin - Pregabalin - Oxcarbazepine - Eslicarbazepine - Zonisamide - Felbamate - Tiagabine - Vigabatrin - Rufinamide - Lacosamide - Perampanel - Cenobamate - Cannabidiol (Epidiolex) - Fenfluramine</li></ul><h3 id=\"86-parkinsons-disease-agents\">8.6 Parkinson&#39;s Disease Agents</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Parkinson&#39;s Disease, Parkinsonism, Restless Legs Syndrome, Hyperprolactinemia (Dopamine Agonists)</p><ul><li><strong>Levodopa Combinations</strong> — Levodopa/Carbidopa - Levodopa/Benserazide</li><li><strong>COMT Inhibitors</strong> — Entacapone - Tolcapone - Opicapone</li><li><strong>Dopamine Agonists</strong> — Pramipexole - Ropinirole - Rotigotine - Apomorphine</li><li><strong>MAO-B Inhibitors</strong> — Selegiline - Rasagiline - Safinamide</li><li><strong>Anticholinergics</strong> — Benztropine - Trihexyphenidyl</li><li><strong>Other</strong> — Amantadine - Istradefylline</li></ul><h3 id=\"87-alzheimers-dementia\">8.7 Alzheimer&#39;s Dementia</h3><p><strong>Primary System:</strong> CNS</p><p><strong>Clinical Uses:</strong> Alzheimer&#39;s Disease (Mild, Moderate, Severe), Mixed Dementia, Parkinson Disease Dementia (Rivastigmine)</p><ul><li><strong>Cholinesterase Inhibitors</strong> — Donepezil - Rivastigmine - Galantamine</li><li><strong>NMDA Antagonist</strong> — Memantine</li><li><strong>Anti-Amyloid Monoclonal Antibodies</strong> — Lecanemab - Donanemab</li></ul><h3 id=\"88-multiple-sclerosis\">8.8 Multiple Sclerosis</h3><p><strong>Primary System:</strong> CNS, Immunological</p><p><strong>Clinical Uses:</strong> Relapsing-Remitting MS (RRMS), Secondary Progressive MS, Primary Progressive MS (Ocrelizumab), Clinically Isolated Syndrome</p><ul><li><strong>Injectable Platforms</strong> — Interferon Beta-1a - Interferon Beta-1b - Glatiramer Acetate</li><li><strong>Oral</strong> — Fingolimod - Siponimod - Ozanimod - Dimethyl Fumarate - Diroximel Fumarate - Teriflunomide - Cladribine</li><li><strong>Infused Monoclonal Antibodies</strong> — Natalizumab - Ocrelizumab - Ofatumumab - Ublituximab - Alemtuzumab</li></ul><h3 id=\"89-analgesics\">8.9 Analgesics</h3><p><strong>Primary System:</strong> CNS (Pain Pathways), Musculoskeletal</p><p><strong>Clinical Uses:</strong> Acute Pain, Chronic Pain, Neuropathic Pain, Cancer Pain, Palliative Care</p><ul><li><strong>NSAIDs &amp; Acetaminophen/Paracetamol</strong> (see above)</li><li><strong>Opioids (Full Agonists)</strong> — Morphine - Hydromorphone - Oxycodone - Fentanyl - Methadone - Codeine - Tramadol - Tapentadol - Hydrocodone - Meperidine/Pethidine</li><li><strong>Opioids (Partial Agonists)</strong> — Buprenorphine - Butorphanol</li><li><strong>Adjuvants</strong> — Gabapentinoids (Gabapentin, Pregabalin) - SNRIs (Duloxetine, Venlafaxine) - TCAs (Amitriptyline, Nortriptyline) - Topical Lidocaine - Capsaicin</li></ul>"},{"معرّف":"9-infectious-disease-drugs-anti-infectives","عنوان":"9. INFECTIOUS DISEASE DRUGS (ANTI-INFECTIVES)","html":"<h3 id=\"91-antibacterials\">9.1 Antibacterials</h3><p><strong>Primary System:</strong> Multi-system (depends on infection site)</p><p><strong>Clinical Uses:</strong> Bacterial Infections: Pneumonia, UTI, Sepsis, Bacteremia, Endocarditis, Meningitis, Skin &amp; Soft Tissue Infections, Intra-abdominal Infections, Osteomyelitis, STIs, TB</p><ul><li><strong>Penicillins</strong> — Penicillin G/V - Amoxicillin - Ampicillin - Dicloxacillin - Flucloxacillin - Nafcillin - Piperacillin</li><li><strong>Beta-Lactamase Inhibitors</strong> — Amoxicillin-Clavulanate - Ampicillin-Sulbactam - Piperacillin-Tazobactam - Ceftazidime-Avibactam - Ceftolozane-Tazobactam - Meropenem-Vaborbactam - Imipenem-Cilastatin-Relebactam</li><li><strong>Cephalosporins (1st)</strong> — Cephalexin - Cefazolin - Cefadroxil</li><li><strong>Cephalosporins (2nd)</strong> — Cefuroxime - Cefoxitin - Cefaclor - Cefprozil</li><li><strong>Cephalosporins (3rd)</strong> — Ceftriaxone - Cefotaxime - Ceftazidime - Cefixime - Cefpodoxime - Cefdinir</li><li><strong>Cephalosporins (4th)</strong> — Cefepime</li><li><strong>Cephalosporins (5th)</strong> — Ceftaroline - Ceftobiprole</li><li><strong>Carbapenems</strong> — Meropenem - Imipenem-Cilastatin - Ertapenem - Doripenem</li><li><strong>Monobactam</strong> — Aztreonam</li><li><strong>Glycopeptides</strong> — Vancomycin - Teicoplanin - Dalbavancin - Oritavancin - Telavancin</li><li><strong>Lipopeptide</strong> — Daptomycin</li><li><strong>Oxazolidinones</strong> — Linezolid - Tedizolid</li><li><strong>Macrolides</strong> — Azithromycin - Clarithromycin - Erythromycin - Fidaxomicin</li><li><strong>Aminoglycosides</strong> — Gentamicin - Amikacin - Tobramycin - Streptomycin</li><li><strong>Tetracyclines</strong> — Doxycycline - Minocycline - Tigecycline - Eravacycline - Omadacycline</li><li><strong>Fluoroquinolones</strong> — Ciprofloxacin - Levofloxacin - Moxifloxacin - Delafloxacin</li><li><strong>Others</strong> — Clindamycin - Metronidazole - Chloramphenicol - TMP-SMX - Nitrofurantoin - Fosfomycin - Colistin/Polymyxin E</li><li><strong>Anti-TB</strong> — Isoniazid - Rifampicin - Pyrazinamide - Ethambutol - Rifabutin - Bedaquiline - Delamanid - Linezolid - Clofazimine - Cycloserine - Ethionamide</li></ul><h3 id=\"92-antifungals\">9.2 Antifungals</h3><p><strong>Primary System:</strong> Multi-system</p><p><strong>Clinical Uses:</strong> Candidemia, Invasive Candidiasis, Aspergillosis, Mucormycosis, Cryptococcal Meningitis, Endemic Mycoses, Dermatophyte Infections</p><ul><li><strong>Azoles</strong> — Fluconazole - Voriconazole - Itraconazole - Posaconazole - Isavuconazole</li><li><strong>Echinocandins (&quot;-fungin&quot;)</strong> — Caspofungin - Micafungin - Anidulafungin</li><li><strong>Polyenes</strong> — Amphotericin B Deoxycholate - Liposomal Amphotericin B</li><li><strong>Antimetabolite</strong> — Flucytosine (5-FC)</li><li><strong>Allylamine</strong> — Terbinafine</li></ul><h3 id=\"93-antivirals-non-hiv\">9.3 Antivirals (Non-HIV)</h3><p><strong>Primary System:</strong> Multi-system</p><p><strong>Clinical Uses:</strong> Herpes Simplex, Varicella-Zoster, CMV, Influenza, Hepatitis B, Hepatitis C, COVID-19</p><ul><li><strong>Anti-Herpes</strong> — Acyclovir - Valacyclovir - Famciclovir - Ganciclovir - Valganciclovir - Foscarnet - Cidofovir</li><li><strong>Anti-Influenza</strong> — Oseltamivir - Zanamivir - Baloxavir Marboxil</li><li><strong>Hepatitis B</strong> — Tenofovir Disoproxil - Tenofovir Alafenamide - Entecavir - Lamivudine - Peginterferon Alfa</li><li><strong>Hepatitis C (DAAs)</strong> — Sofosbuvir - Ledipasvir - Velpatasvir - Glecaprevir/Pibrentasvir - Daclatasvir - Grazoprevir/Elbasvir</li><li><strong>COVID-19</strong> — Remdesivir - Nirmatrelvir/Ritonavir (Paxlovid) - Molnupiravir</li></ul><h3 id=\"94-antiretrovirals-hiv\">9.4 Antiretrovirals (HIV)</h3><p><strong>Primary System:</strong> Immunological</p><p><strong>Clinical Uses:</strong> HIV-1 Infection (Treatment &amp; Prevention/PrEP/PEP)</p><ul><li><strong>NRTIs</strong> — Tenofovir DF (TDF) - Tenofovir AF (TAF) - Emtricitabine (FTC) - Lamivudine (3TC) - Abacavir - Zidovudine (AZT)</li><li><strong>NNRTIs</strong> — Efavirenz - Rilpivirine - Etravirine - Doravirine</li><li><strong>Protease Inhibitors</strong> — Darunavir/Ritonavir - Atazanavir/Ritonavir</li><li><strong>Integrase Inhibitors (INSTIs)</strong> — Dolutegravir - Bictegravir - Raltegravir - Cabotegravir</li><li><strong>Entry Inhibitor</strong> — Maraviroc (CCR5)</li><li><strong>Pharmacokinetic Enhancers</strong> — Ritonavir - Cobicistat</li></ul>"},{"معرّف":"10-emergency-critical-care-drugs-cross-system","عنوان":"10. EMERGENCY & CRITICAL CARE DRUGS (Cross-System)","html":"<h3 id=\"101-cardiac-arrest-acls\">10.1 Cardiac Arrest (ACLS)</h3><ul><li>Epinephrine - Amiodarone - Lidocaine - Magnesium Sulfate - Sodium Bicarbonate - Calcium Gluconate/Chloride</li></ul><h3 id=\"102-shock-pressors\">10.2 Shock &amp; Pressors</h3><ul><li>Norepinephrine - Epinephrine - Vasopressin - Phenylephrine - Dobutamine - Milrinone - Dopamine</li></ul><h3 id=\"103-reversal-antidotes\">10.3 Reversal / Antidotes</h3><ul><li>Naloxone (Opioids) - Flumazenil (Benzodiazepines) - N-Acetylcysteine (Acetaminophen) - Digoxin Immune Fab (Digoxin) - Glucagon (Beta-Blocker) - Hydroxocobalamin (Cyanide) - Lipid Emulsion 20% (LAST) - Protamine (Heparin) - Vitamin K / 4F-PCC (Warfarin) - Idarucizumab (Dabigatran) - Andexanet Alfa (Xa Inhibitors)</li></ul><h3 id=\"104-status-epilepticus\">10.4 Status Epilepticus</h3><ul><li>Lorazepam IV - Midazolam IM - Fosphenytoin - Levetiracetam - Valproate IV - Propofol (refractory)</li></ul><h3 id=\"105-anaphylaxis\">10.5 Anaphylaxis</h3><ul><li>Epinephrine IM - Diphenhydramine - Famotidine/Ranitidine - Methylprednisolone - Albuterol (nebulized)</li></ul><h3 id=\"106-hyperkalemia-emergency\">10.6 Hyperkalemia (Emergency)</h3><ul><li>Calcium Gluconate 10% - Insulin + Dextrose - Sodium Bicarbonate - Albuterol (High-dose nebulized) - Furosemide - Sodium Zirconium Cyclosilicate / Patiromer</li></ul><div class=\"كتلة تحقّق\"><p class=\"كتلة-عنوان\">Verification footer</p><p><strong>Guidelines used:</strong> none retrieved for this file; class-level pharmacology [PK].</p><p><strong>Generated:</strong> 12 September 2026.</p><p><strong>Could not verify — read this before quoting:</strong> the source document carries no citations at all. Nothing here is sourced; every figure is <strong><button class=\"وسم-دليل\" type=\"button\" data-وسم=\"?\" title=\"لم يُعثر على رقم موثوق — no reliable data located\">?</button></strong>.</p><p><strong>Confirm before clinical application:</strong> treat this file as revision notes. For any treatment decision go to the primary guideline, not to this page.</p></div>"}],"مصادر":[]});
